const norm=x=>((x%360)+360)%360, sg=x=>Math.floor(norm(x)/30), dg=x=>norm(x)%30, R=Math.PI/180;
const fdg=x=>`${td(Math.floor(dg(x)))}°${td(String(Math.floor((dg(x)%1)*60)).padStart(2,'0'))}′`, pos=x=>`${SN[sg(x)]} ${fdg(x)}`;
const MS=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'], fd=t=>`${td(t.getDate())} ${MS[t.getMonth()]} ${td(t.getFullYear()+543)}`;
const UT=t=>(typeof avW141==='function'?avW141(t):t.getTime())-252e5;
function cuspsOf(sys,asc,mc,ramc,eps,lat){ const c=[];
if(sys==='W'){ for(let i=0;i<12;i++) c.push(sg(asc)*30+i*30); return c; }
if(sys==='E'){ for(let i=0;i<12;i++) c.push(norm(asc+i*30)); return c; }
const q=(a,b,k)=>norm(a+norm(b-a)*k);
if(sys==='O'){ const ic=norm(mc+180), ds=norm(asc+180); return [asc,q(asc,ic,1/3),q(asc,ic,2/3),ic,q(ic,ds,1/3),q(ic,ds,2/3),ds,q(ds,mc,1/3),q(ds,mc,2/3),mc,q(mc,asc,1/3),q(mc,asc,2/3)]; }
const e=eps*R, f=lat*R; const cusp=(k,up)=>{ let lam=norm(mc+(up?k*90:180-k*90)); for(let i=0;i<12;i++){ const d=Math.asin(Math.sin(e)*Math.sin(lam*R)); const x=Math.tan(f)*Math.tan(d); if(Math.abs(x)>=1) return null; const ad=Math.asin(x)/R; const ra=up?ramc+k*(90+ad):ramc+180-k*(90-ad); lam=norm(Math.atan2(Math.sin(ra*R),Math.cos(ra*R)*Math.cos(e))/R); } return lam; };
const h11=cusp(1/3,true), h12=cusp(2/3,true), h2=cusp(2/3,false), h3=cusp(1/3,false); if([h11,h12,h2,h3].some(v=>v==null||isNaN(v))) return null;
return [asc,h2,h3,norm(mc+180),norm(h11+180),norm(h12+180),norm(asc+180),norm(h2+180),norm(h3+180),mc,h11,h12]; }
function chart(t,lat,lon,sys){ const ut=UT(t), e=eph111(ut), P={}, S={};
['SU','MO','ME','VE','MA','JU','SA','UR','NE','PL','NN'].forEach(k=>P[k]=e[k].lon);
const e2=eph111(ut+864e5); ['SU','MO','ME','VE','MA','JU','SA','UR','NE','PL'].forEach(k=>{ let d=e2[k].lon-e[k].lon; if(d>180) d-=360; if(d<-180) d+=360; S[k]=d; }); S.NN=-0.053;
const ramc=norm(e.gmst+lon), r=ramc*R, ep=e.eps*R, f=lat*R;
const mc=norm(Math.atan2(Math.sin(r),Math.cos(r)*Math.cos(ep))/R), asc=norm(Math.atan2(Math.cos(r),-(Math.sin(r)*Math.cos(ep)+Math.tan(f)*Math.sin(ep)))/R);
P.AS=asc; P.MC=mc; const C={t,ut,lat,lon,P,S,asc,mc,ramc,eps:e.eps}; C.sys=sys||'P'; C.cusps=cuspsOf(C.sys,asc,mc,ramc,e.eps,lat)||cuspsOf('E',asc,mc,ramc,e.eps,lat); if(!cuspsOf(C.sys,asc,mc,ramc,e.eps,lat)) C.sysFail=1;
C.house=x=>{ for(let i=0;i<12;i++){ const a=C.cusps[i], b=C.cusps[(i+1)%12]; if(norm(x-a)<norm(b-a)) return i+1; } return 1; }; return C; }
function aspects(C,D,opt){ opt=opt||{}; const lv=opt.lv||2, sc=opt.sc||1, out=[], ks=opt.keys||PTS, ks2=opt.keys2||ks, same=!D; D=D||C;
ks.forEach((a,i)=>ks2.forEach((b,j)=>{ if(same&&j<=i) return; if(same&&((a==='AS'&&b==='MC')||(a==='MC'&&b==='AS'))) return; const x=C.P[a], y=D.P[b]; if(x==null||y==null) return; const d=Math.abs(((x-y+540)%360)-180);
for(const [ang,n,orb,m,col,l] of ASP){ if(l>lv) continue; const o=Math.abs(d-ang), ob=(opt.orb?opt.orb:orb*sc)*((a==='NN'||b==='NN'||a==='MC'||b==='MC')?0.6:1); if(o<=ob){ out.push({a,b,ang,n,o,m,col,l,ob}); break; } } }));
return out.sort((p,q)=>p.l-q.l||p.o-q.o); }
const WGT={SU:3,MO:3,AS:3,ME:2,VE:2,MA:2,JU:1,SA:1,UR:.5,NE:.5,PL:.5};
function balance(C){ const el=[0,0,0,0], md=[0,0,0], yy=[0,0], pl={e:[[],[],[],[]],m:[[],[],[]]}; Object.keys(WGT).forEach(k=>{ const s=sg(C.P[k]), w=WGT[k]; el[s%4]+=w; md[s%3]+=w; yy[s%2]+=w; pl.e[s%4].push(k); pl.m[s%3].push(k); }); return {el,md,yy,pl}; }
function hemis(C){ const ks=['SU','MO','ME','VE','MA','JU','SA','UR','NE','PL']; let up=0,lo=0,le=0,ri=0; ks.forEach(k=>{ const h=C.house(C.P[k]); if(h>=7) up++; else lo++; if([10,11,12,1,2,3].includes(h)) le++; else ri++; }); return {up,lo,le,ri}; }
function patterns(C,as){ const has=(a,b,ang)=>as.some(x=>((x.a===a&&x.b===b)||(x.a===b&&x.b===a))&&x.ang===ang); const ks=['SU','MO','ME','VE','MA','JU','SA','UR','NE','PL','AS','MC'], out=[];
for(let i=0;i<ks.length;i++) for(let j=i+1;j<ks.length;j++) for(let k=j+1;k<ks.length;k++){ const a=ks[i],b=ks[j],c=ks[k];
if(has(a,b,120)&&has(b,c,120)&&has(a,c,120)){ const kite=ks.filter(d=>![a,b,c].includes(d)&&[a,b,c].some(x=>has(x,d,180))); out.push(['ตรีโกณใหญ่',[a,b,c],G,'ชีวิตได้มาง่าย มีพรสวรรค์ตามธาตุนั้น แต่อาจเกียจคร้าน'+(kite.length?` · มี${PN[kite[0]]}เล็งเข้ามาเป็นรูปว่าว ช่วยกระตุ้นให้ใช้พรสวรรค์`:'')]); }
[[a,b,c],[a,c,b],[b,c,a]].forEach(([p,q,r])=>{ if(has(p,q,180)&&has(p,r,90)&&has(q,r,90)) out.push(['ทีสแควร์',[p,q,r],B,`ตึงเครียด แต่ทำให้มานะบากบั่น จุดยอดคือ${PN[r]}`]); if(has(p,q,60)&&has(p,r,150)&&has(q,r,150)) out.push(['ดัชนีพระเจ้า (Yod)',[p,q,r],P,`เหตุการณ์ที่เลี่ยงไม่ได้ จุดยอด${PN[r]}บอกว่าเป็นเรื่องอะไร`]); }); }
for(let i=0;i<ks.length;i++) for(let j=i+1;j<ks.length;j++){ if(!has(ks[i],ks[j],180)) continue; for(let k=0;k<ks.length;k++) for(let l=k+1;l<ks.length;l++){ if([i,j].includes(k)||[i,j].includes(l)) continue; const c=ks[k], d=ks[l]; if(has(c,d,180)&&has(ks[i],c,90)&&has(ks[i],d,90)&&has(ks[j],c,90)&&has(ks[j],d,90)&&i<k) out.push(['กางเขนใหญ่',[ks[i],ks[j],c,d],B,'แรงกดดันรอบด้าน ถ้าผ่านบททดสอบได้จะสำเร็จมาก ให้หาจุดที่ทำมุมแบบอื่นเป็นทางออก']); } }
const sp=['SU','MO','ME','VE','MA','JU','SA','UR','NE','PL']; for(let s=0;s<12;s++){ const inS=sp.filter(k=>sg(C.P[k])===s); if(inS.length>=3) out.push(['สเตลเลียม',inS,GD,`ดาว ${td(inS.length)} ดวงรวมในราศี${SN[s]} เป็นพื้นที่ที่มีน้ำหนักมากในชีวิต`]); }
const seen={}; return out.filter(o=>{ const k=o[0]+o[1].slice().sort().join(); if(seen[k]) return false; seen[k]=1; return true; }); }
const I={book:'<path d="M4 5a2 2 0 0 1 2-2h13v16H6a2 2 0 0 0-2 2z"/><path d="M8 7h7M8 11h7"/>',star:'<path d="M12 3l2.6 5.5 6 .8-4.4 4.1 1.1 5.9L12 16.4 6.7 19.3l1.1-5.9L3.4 9.3l6-.8z"/>',sky:'<circle cx="12" cy="12" r="3.5"/><ellipse cx="12" cy="12" rx="9.5" ry="4"/>',wheel:'<circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18"/>',drop:'<path d="M12 3c3.5 4.5 6 7.6 6 10.5a6 6 0 0 1-12 0C6 10.6 8.5 7.5 12 3z"/>',house:'<path d="M3 11l9-7 9 7"/><path d="M5 10v10h14V10"/>',link:'<path d="M10 14a4.5 4.5 0 0 0 6.4 0l3-3a4.5 4.5 0 0 0-6.4-6.4l-1 1"/><path d="M14 10a4.5 4.5 0 0 0-6.4 0l-3 3a4.5 4.5 0 0 0 6.4 6.4l1-1"/>',flow:'<path d="M4 6h10M4 12h16M4 18h7"/><path d="M17 3l3 3-3 3"/>',chart:'<path d="M3 20h18M6 16l4-6 4 3 5-8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3.5 2"/>',heart:'<path d="M12 20s-7.5-4.6-7.5-10A4.3 4.3 0 0 1 12 7.4 4.3 4.3 0 0 1 19.5 10c0 5.4-7.5 10-7.5 10z"/>',brief:'<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M9 7V5h6v2M3 13h18"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7.5v.5"/>',warn:'<path d="M12 3l9.5 17h-19z"/><path d="M12 10v4.5M12 17.5v.5"/>',spark:'<path d="M12 3v4M12 17v4M3 12h4M17 12h4M6 6l2.5 2.5M15.5 15.5L18 18M6 18l2.5-2.5M15.5 8.5L18 6"/>',arc:'<path d="M4 18a8 8 0 0 1 16 0"/><path d="M12 18l4-7"/>'};
const ic=(n,c,s)=>`<svg viewBox="0 0 24 24" width="${s||18}" height="${s||18}" style="width:${s||18}px!important;height:${s||18}px!important;flex:none" fill="none" stroke="${c||'currentColor'}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${I[n]}</svg>`;
