const K=['SU','MO','MA','ME','JU','VE','SA','RA','KE','UR'], NUM={SU:1,MO:2,MA:3,ME:4,JU:5,VE:6,SA:7,RA:8,KE:9,UR:0}, N2K={1:'SU',2:'MO',3:'MA',4:'ME',5:'JU',6:'VE',7:'SA',8:'RA',9:'KE',0:'UR'};
const PNM={1:'อาทิตย์',2:'จันทร์',3:'อังคาร',4:'พุธ',5:'พฤหัสบดี',6:'ศุกร์',7:'เสาร์',8:'ราหู',9:'เกตุ',0:'มฤตยู'};
const PCL={1:'#e8743b',2:'#c9b458',3:'#e05f8a',4:'#2faa5a',5:'#f08a24',6:'#4aa3ff',7:'#7a5ab8',8:'#8a6e4b',9:'#5d8aa8',0:'#3fa7a0'};
