W.forEach(w=>{ const a0=(w.s-X.bt)/(365.25*864e5), a1=(w.e-X.bt)/(365.25*864e5), h=Math.min(118,w.sev.s*38), [c]=lv(w.sev.s); tl+=`<rect x="${xa(a0)}" y="${142-h}" width="${Math.max(3,xa(a1)-xa(a0))}" height="${h}" rx="3" fill="${c}" fill-opacity="${w.e<now?.45:.9}"/><text x="${(xa(a0)+xa(a1))/2}" y="${136-h}" font-size="9" text-anchor="middle" fill="currentColor">${w.k}</text>`; });
const na=(now-X.bt)/(365.25*864e5); tl+=`<line x1="${xa(na)}" x2="${xa(na)}" y1="14" y2="146" stroke="${A}" stroke-width="1.5" stroke-dasharray="3 3"/><text x="${xa(na)}" y="11" font-size="10" text-anchor="middle" fill="${A}">ปัจจุบัน</text><text x="20" y="168" font-size="9.5" fill="currentColor" opacity=".7">ช่วงราหูจรทับหรือเล็งราหูเดิมตลอดอายุ ๙๐ ปี ความสูงคือความรุนแรงหลังปรับตามพื้นดวง</text></svg>`;
const ref=cur||nx; const [rc,rl]=ref?lv(ref.sev.s):[G,'—'];
