document.addEventListener('click',ev=>{ const e=ev.target.closest&&ev.target.closest('#rh331Out [data-rht]'); if(!e) return; TAB=e.dataset.rht; render(); document.getElementById('rh331P').scrollIntoView({block:'start',behavior:'smooth'}); });
