function ctx(){ const W=typeof WSTATE!=='undefined'?WSTATE:null; if(!W||!W.bt) return null; let T; try{ T=getTransit(); }catch(e){} if(!T||isNaN(T)) T=new Date(); const bt=new Date(+W.bt);
let wd=0; try{ wd=thaiWeekday(bt); }catch(e){ wd=(bt.getDay()+1)%7; } const day=wd===0?7:wd; let lm=null; try{ lm=thaiLunar(bt); }catch(e){} const mon=lm&&lm.mon?((lm.mon-1)%12)+1:((bt.getMonth()+7)%12)+1;
let cy=bt.getFullYear(); if(bt<new Date(cy,3,13)) cy--; const yr=((cy-4)%12+12)%12; let full=T.getFullYear()-bt.getFullYear(); if(T<new Date(T.getFullYear(),bt.getMonth(),bt.getDate())) full--;
return {bt,T,day,mon,yr,full,age:full+1}; }
