function dig(k,x){ const s=sg(x), d=dg(x); if(EX[k]&&EX[k][0]===s) return ['อุจจ์',G,2]; if(EX[k]&&(EX[k][0]+6)%12===s) return ['นิจ',B,-2]; if(MT[k]&&MT[k][0]===s&&d>=MT[k][1]&&d<MT[k][2]) return ['มูลตรีโกณ',TR,1.5]; if(OWN[k]&&OWN[k].includes(s)) return ['เกษตร',TR,1]; return ['',GR,0]; }
