function ctx(){ const W=typeof WSTATE!=='undefined'?WSTATE:null; if(!W||!W.bt||!W.nat) return null; let T; try{ T=getTransit(); }catch(e){} if(!T||isNaN(T)) T=new Date(); let TC=null; try{ TC=chartAt(T,W.lat,W.lon); }catch(e){} const bt=new Date(+W.bt); let tk={}, tj={}; try{ tk=taksaNatal(bt).m; }catch(e){} try{ tj=taksaJrOf(bt,T); }catch(e){}
return {bt,T,N:W.nat,TC,L:sg(W.nat.pos.LA),tk,tj}; }
