function judge(X,ch,n,m){ const s=sOf(ch,n), h=hS(X,s), r=rel(h), st=stdOf(n,ch), role=roleOf(m,n), kali=m['กาลกิณี'], withK=kali!=null&&kali!==n&&sOf(ch,kali)===s;
const goodStd=/เกษตร|อุจจ์|ราชาโชค|มหาจักร|อุจจาวิลาส/.test(st), badStd=/นิจ|ประ/.test(st), goodRole=['เดช','ศรี','มนตรี'].includes(role), badRole=role==='กาลกิณี';
let v=0; if(r) v+=1; if(dus(h)) v-=1; if(r&&goodStd) v+=1; if(r&&goodRole) v+=.7; if(badRole||withK) v-=1; if(badStd&&!dus(h)) v-=.7;
return {n,s,h,r,st,role,withK,goodStd,badStd,v}; }
