function hitsTo(tgtS,tgtName,P,keys,tagP){ const out=[]; keys.forEach(k=>{ if(P[k]==null) return; const r=rel(tgtS,S(P,k)); if(r) out.push({t:`${NM[k]}${tagP} ${r[0]}${tgtName}`,w:r[1],k}); }); return out; }
