const lvOf=x=>x>=5?['เฝ้าระวังมาก',B]:x>=4?['ระวัง',O]:x>=3?['ปานกลาง',Y]:['ปกติ',G];
const fd=t=>`${td(t.getDate())} ${MO[t.getMonth()]} ${td(t.getFullYear()+543)}`;
function wheel(X,TP,PL,marks){ const cx=170,cy=170,R=150,R2=112; let s=`<svg viewBox="0 0 340 340" class="dv0svg sq"><circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="currentColor" stroke-opacity=".3"/><circle cx="${cx}" cy="${cy}" r="${R2}" fill="none" stroke="currentColor" stroke-opacity=".2"/><circle cx="${cx}" cy="${cy}" r="62" fill="none" stroke="currentColor" stroke-opacity=".15"/>`;
const ang=i=>(-90-i*30)*Math.PI/180, P=(r,a)=>[cx+r*Math.cos(a),cy+r*Math.sin(a)];
for(let i=0;i<12;i++){ const a0=ang(i)+Math.PI/12, [x1,y1]=P(62,a0), [x2,y2]=P(R,a0); s+=`<path d="M${x1} ${y1}L${x2} ${y2}" stroke="currentColor" stroke-opacity=".2"/>`;
const mk=(marks||{})[i]; if(mk){ const a1=ang(i)+Math.PI/12, a2=ang(i)-Math.PI/12, [p1,q1]=P(R,a1),[p2,q2]=P(R,a2),[p3,q3]=P(62,a2),[p4,q4]=P(62,a1); s+=`<path d="M${p1} ${q1}A${R} ${R} 0 0 1 ${p2} ${q2}L${p3} ${q3}A62 62 0 0 0 ${p4} ${q4}Z" fill="${mk}" fill-opacity=".14"/>`; }
const [tx,ty]=P(R-11,ang(i)); s+=`<text x="${tx}" y="${ty+4}" text-anchor="middle" font-size="9.5" fill="currentColor" opacity=".7">${SN[i]}</text>`; }
const put=(keys,Pos,r0,hol)=>{ const by={}; keys.forEach(k=>{ if(Pos[k]==null) return; const sg=k==='LA'?sgOf(Pos.LA):S(Pos,k); (by[sg]=by[sg]||[]).push(k); });
Object.entries(by).forEach(([sg,ks])=>ks.forEach((k,j)=>{ const a=ang(+sg)+(j-(ks.length-1)/2)*0.16, [x,y]=P(r0-(j%2)*10,a); s+=`<circle cx="${x}" cy="${y}" r="8" fill="${hol?'none':PC[k]}" stroke="${PC[k]}" stroke-width="1.6"/><text x="${x}" y="${y+3.5}" text-anchor="middle" font-size="9.5" font-weight="700" fill="${hol?PC[k]:'#fff'}">${NO[k]}</text>`; })); };
put(['LA',...K],{...X.N},88,0); if(TP) put(K,TP,R2+18-24,1);
if(PL!=null){ const [x,y]=P(R2-6,ang(PL)); s+=`<rect x="${x-11}" y="${y-8}" width="22" height="15" rx="4" fill="#e5202a" fill-opacity=".85"/><text x="${x}" y="${y+3.5}" text-anchor="middle" font-size="9" font-weight="700" fill="#fff">ลจ</text>`; }
return s+`<text x="${cx}" y="${cy-4}" text-anchor="middle" font-size="11" fill="currentColor" opacity=".8">ทึบ = ดาวเดิม</text><text x="${cx}" y="${cy+12}" text-anchor="middle" font-size="11" fill="currentColor" opacity=".8">โปร่ง = ดาวจร</text></svg>`; }
function tRule(){ const rels=[[0,'ทับ (กุม)','อยู่ราศีเดียวกัน'],[6,'เล็ง','ราศีที่ ๗'],[2,'โยคหน้า','ราศีที่ ๓'],[10,'โยคหลัง','ราศีที่ ๑๑'],[4,'ตรีโกณหน้า','ราศีที่ ๕'],[8,'ตรีโกณหลัง','ราศีที่ ๙'],[1,'ขนาบ','ราศีที่ ๒ และ ๑๒ พร้อมกัน']];
const cx=150,cy=150,R=120, ang=i=>(-90-i*30)*Math.PI/180; let w=`<svg viewBox="0 0 300 300" class="dv0svg sq"><circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="currentColor" stroke-opacity=".25"/>`;
const col={0:B,6:B,2:O,10:O,4:Y,8:Y,1:P,11:P};
for(let i=0;i<12;i++){ const a=ang(i), x=cx+R*Math.cos(a), y=cy+R*Math.sin(a), c=col[i]; if(c&&i) w+=`<path d="M${cx} ${cy}L${x} ${y}" stroke="${c}" stroke-dasharray="${i===1||i===11?'3 3':''}" stroke-width="1.6"/>`; w+=`<circle cx="${x}" cy="${y}" r="15" fill="${c||'none'}" fill-opacity="${c?.85:0}" stroke="${c||'currentColor'}" stroke-opacity="${c?1:.3}"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="11" font-weight="700" fill="${c?'#fff':'currentColor'}">${td(i+1)}</text>`; }
w+=`<circle cx="${cx}" cy="${cy}" r="24" fill="#e5202a"/><text x="${cx}" y="${cy+4}" text-anchor="middle" font-size="12" font-weight="700" fill="#fff">ลัคนา</text></svg>`;
const rules=[['ลัคนาเข้าเกณฑ์เคราะห์ร้าย','ดาวร้าย ๖ ดวง คือ อังคาร เสาร์ ราหู เกตุ มฤตยู และเนปจูน จรมาทับ เล็ง โยค ตรีโกณ หรือขนาบลัคนาเดิมหรือลัคนาจร'],['ลัคนาเข้าเกณฑ์มรณะ','ราศีที่ ๘ จากลัคนาเป็นราศีมรณะ ดาวในราศีนั้นเป็นดาวมรณะ ถ้าว่างใช้เจ้าราศี เมื่อดาวมรณะจรมาสัมพันธ์กับลัคนา หรือดาวมรณะหรือลัคนาจรเข้าราศีมรณะ'],['ดาวเสวยอายุเข้าเกณฑ์มรณะ','ดาวเสวยอายุองค์ละ ๑๐ ปี เรียงจันทร์ อาทิตย์ พุธ ศุกร์ อังคาร พฤหัสบดี เสาร์ มฤตยู เนปจูน พลูโต แล้วดูดาวมรณะของดาวเสวยแบบเดียวกับลัคนา'],['ดาวอายุเข้าเกณฑ์มรณะ','ดาวอายุตามวันเกิด แล้วดูดาวมรณะของดาวอายุแบบเดียวกัน'],['ดาววัน เดือน ปีเกิดเข้าเกณฑ์มรณะ','ดาววันคือจันทร์ (ย้ายเร็วที่สุด) ดาวเดือนคืออาทิตย์ ดาวปีคือพฤหัสบดี ดูปีก่อน แล้วเดือน แล้ววัน วันที่จันทร์จรเข้าเกณฑ์คือวันที่ตำรากำหนด']];
return card(GD,'book','ที่มาของตำรา',`<p>หนังสืออนุสรณ์งานพระราชทานเพลิงศพ พ.ศ. ๒๕๑๙ ผู้เขียนคือ<b>นายตุ๋ย มั่นศรีกุล</b> อดีตข้าราชการกรมไปรษณีย์โทรเลข ท่านศึกษาโหราศาสตร์ทั้งแบบลัคนาเดียวและสิบลัคนา แต่เขียนเล่มนี้ด้วยแบบลัคนาเดียว และตั้งใจให้คนทั่วไปที่มีดวงชะตาและปฏิทินดาวใช้ตรวจเองได้</p><p>ภาคแรกของเล่มเป็นประวัติและคติธรรมจากพระเถระหลายรูป ใจความร่วมกันคือ ความเกิด แก่ เจ็บ ตายเป็นธรรมดา ชีวิตที่มีค่าคือชีวิตที่ทำกรรมดี ภาคหลังเป็นหลักเกณฑ์ ๕ ข้อ พร้อมตัวอย่าง ๑๐ ดวง และข้อยกเว้น ๒ ข้อ</p>`)+
card(B,'warn','ใช้อย่างไรในโหมดนี้',`<p>ตำราตั้งชื่อว่าดวงวันเกิดบอกวันตาย โหมดนี้นำหลักเดียวกันมาใช้เป็น<b>ช่วงที่ควรเฝ้าระวังสุขภาพและอุบัติเหตุ</b> ไม่ได้บอกวันตายของผู้ใดเป็นการเจาะจง ผู้เขียนเองย้ำว่าแม้เข้าเกณฑ์ครบ ๕ ข้อก็ยังไม่ตายได้ เพราะดาวอายุดีเด่นหรือบุญกุศลช่วยไว้</p><p class="note">ข้อมูลนี้เป็นความเชื่อทางโหราศาสตร์ ไม่ใช่การวินิจฉัยทางการแพทย์ ถ้ามีอาการผิดปกติควรพบแพทย์</p>`)+
card(P,'list','หลักเกณฑ์ ๕ ข้อ',`<div class="dv0g w">${rules.map(([t,d],i)=>`<div class="dv0q" style="--c:${[B,O,P,A,TR][i]}"><div class="h"><b>${td(i+1)}</b><span>${t}</span></div><p>${d}</p></div>`).join('')}</div>`)+
`<div class="dv0two"><div>${card(O,'orbit','ความสัมพันธ์ที่นับว่าให้โทษ',`<div class="dv0wb">${w}</div>`+rels.map(([d,n,x])=>kv(n,x)).join(''))}</div><div>${card(A,'clock','ลัคนาจรและดาวเสวยอายุ',`<p>ลัคนาจรเดินหน้าปีละ ๑ ราศี อายุครบ ๑ ปีย่าง ๒ ลัคนาจรอยู่ราศีถัดจากลัคนาเดิม ครบ ๑๒ ปีกลับมาทับลัคนาเดิม แล้วหมุนต่อไปจนสิ้นอายุ ลัคนาจรที่ไปสัมพันธ์กับดาวร้ายในดวงเดิมก็นับว่าเข้าเกณฑ์เคราะห์ร้ายเช่นกัน</p>${DASA.map((k,i)=>kv(`อายุ ${td(i*10+1)}–${td(i*10+10)} ปี`,`${pl(k)} ${NM[k]}`)).join('')}`)}</div></div>`+
`<div class="dv0two"><div>${card(TR,'grid','เจ้าราศี (ใช้หาดาวมรณะเมื่อราศีมรณะว่าง)',SN.map((s,i)=>kv('ราศี'+s,`${pl(LR[i])} ${NM[LR[i]]}`)).join('')+'<p class="note">ตำรานี้ใช้เจ้าราศีแบบดาวนอก เมษเป็นพลูโต พฤษภเป็นราหู เมถุนเป็นเกตุ กุมภ์เป็นมฤตยู มีนเป็นเนปจูน</p>')}</div><div>${card(Y,'user','ดาวอายุตามวันเกิด',WDN.map((d,i)=>kv('เกิดวัน'+d,`${pl(AYU[i])} ${NM[AYU[i]]}`)).join(''))}</div></div>`+
card(G,'lotus','ข้อยกเว้น ๒ ข้อ',`<ol class="dv0ol"><li><b>ดาวอายุดีเด่น</b> เช่น ดาวอายุอยู่ราศีเกษตรของตนหรือของดาวที่เป็นมิตร มีดาวคู่ธาตุคู่มิตรหนุน ตำรายกตัวอย่างผู้ที่ดาวอายุมีดาวให้คุณถึง ๖ ดวง จึงอายุยืนถึง ๘๙ ปี</li><li><b>บารมีกุศลผลบุญ</b> ผู้ที่ดาวอายุอ่อน มีดาวร้ายให้โทษหลายดวง แต่หมั่นทำบุญ ใส่บาตร ทอดกฐิน ช่วยเหลือสาธารณะ ก็อายุยืนผ่านช่วงอันตรายไปได้ ผู้เขียนชวนให้ทุกคนทำบุญตามกำลัง ไม่ว่าดวงแข็งหรืออ่อน</li></ol>`)+
card(GR,'info','จากตัวอย่าง ๑๐ ดวงในเล่ม',`<p>ตัวอย่างครอบคลุมอายุตั้งแต่ ๒ ถึง ๙๑ ปี ทั้งป่วย อุบัติเหตุ และถูกทำร้าย ทุกดวงเข้าเกณฑ์ครบทั้ง ๕ ข้อ และวันเกิดเหตุตรงกับวันที่จันทร์จร (ดาววัน) เข้าเกณฑ์มรณะ ผู้เขียนแนะให้ตรวจเป็นช่วงละ ๓ หรือ ๖ เดือน ไล่จากข้อ ๑ ไปข้อ ๕</p><p class="note">โหมดนี้ไม่แสดงชื่อและดวงของบุคคลจริงในตัวอย่าง</p>`); }
function tNatal(X){ const L=X.L, m=marana(L,X.N), mk={}; mk[L]=A; mk[m.ms]=B;
const D=DASA[Math.min(9,Math.floor(X.age/10))], AK=AYU[X.wd]||'MO';
const st=k=>{ const s=S(X.N,k), mm=marana(s,X.N), sr=strong(X,k); return `<div class="dv0q" style="--c:${PC[k]}"><div class="h">${pl(k)}<span>${NM[k]}เดิม ราศี${SN[s]}</span>${tag(sr.lv[0],sr.lv[1])}</div><p>ราศีมรณะ ${SN[mm.ms]} · ดาวมรณะ ${mm.set.map(pl).join(' ')}${mm.own?' (เจ้าราศี)':''}</p><p class="note">${sr.why.join(' · ')||'ไม่มีดาวหนุนหรือดาวกดเด่นชัด'}</p></div>`; };
const badL=hitsTo(L,'ลัคนา',X.N,BAD,'เดิม').concat(sandwich(L,'ลัคนา',X.N,BAD,'เดิม'));
const life=[]; for(let a=0;a<96;a++){ const PL=(L+a)%12, e=[...hitsTo(PL,'',X.N,BAD,'').filter(x=>x.w>=1),...sandwich(PL,'',X.N,BAD,'')]; life.push((PL===m.ms?1:0)+e.length); }
const lg=`<svg viewBox="0 0 660 120" class="dv0svg">${life.map((w,a)=>{ const x=20+(a%48)*13, y=a<48?14:66, c=w>=2?B:w>=1?O:G; return `<rect x="${x}" y="${y}" width="11" height="36" rx="3" fill="${c}" fill-opacity="${w?.85:.35}"><title>อายุ ${a} ปีเต็ม ย่าง ${a+1}: ลัคนาจรราศี${SN[(L+a)%12]}</title></rect>${a%6===0?`<text x="${x+5.5}" y="${y+48}" text-anchor="middle" font-size="9" fill="currentColor" opacity=".7">${td(a+1)}</text>`:''}`; }).join('')}</svg>`;
const sA=strong(X,AK);
return `<div class="dv0two"><div>${card(GD,'orbit','ดวงวันเกิด',`<div class="dv0wb">${wheel(X,null,null,mk)}</div><p class="note">ช่องฟ้า = ลัคนา (ราศี${SN[L]}) · ช่องแดง = ราศีมรณะของลัคนา (ราศี${SN[m.ms]})</p>`)}</div><div>${card(B,'warn','ลัคนาและดาวมรณะของลัคนา',`${kv('ลัคนาเดิม','ราศี'+SN[L])}${kv('ราศีมรณะ (ที่ ๘)','ราศี'+SN[m.ms])}${kv('ดาวมรณะ',m.set.map(k=>pl(k)+' '+NM[k]).join(' ')+(m.own?' (เจ้าราศี)':''))}<p><b>ดาวร้ายเดิมที่สัมพันธ์ลัคนา</b></p>${badL.length?'<ul class="dv0ck">'+badL.map(x=>`<li class="b">${ic('warn',B,15)}<span>${x.t}</span></li>`).join('')+'</ul>':'<p class="note">ไม่มีดาวร้ายเดิมสัมพันธ์กับลัคนา พื้นดวงลัคนาไม่ถูกบีบ</p>'}`)}</div></div>`+
card(G,'shield','ข้อยกเว้นข้อ ๑: ดาวอายุดีเด่นหรือไม่',`<div class="dv0verdict" style="--c:${sA.lv[1]}">${ic(sA.sc>=3?'ok':sA.sc>=1?'info':'warn',sA.lv[1],22)}<div><b>ดาวอายุ (${NM[AK]}) ${sA.lv[0]}</b><p>${sA.why.join(' · ')||'ไม่มีดาวหนุน'} · คะแนน ${td(sA.sc)}</p><p class="note">${sA.sc>=3?'ตำราถือว่าดาวอายุดีเด่นช่วยชะลอเคราะห์ ทำให้ผ่านช่วงเข้าเกณฑ์ไปได้':sA.sc>=1?'ดาวอายุพอมีกำลัง ควรเสริมด้วยบุญกุศลตามข้อยกเว้นข้อ ๒':'ดาวอายุค่อนข้างอ่อน ตำราแนะให้หมั่นทำบุญทำทานตามกำลัง เป็นบารมีช่วยต่ออายุ'}</p></div></div>`)+
card(P,'user','ดาวหลักทั้ง ๕ ข้อ และดาวมรณะประจำตัว',`<div class="dv0g w">${[D,AK,'JU','SU','MO'].filter((k,i,a)=>a.indexOf(k)===i).map(st).join('')}</div><p class="note">ดาวเสวยอายุตอนนี้ ${NM[D]} (อายุ ${td(Math.floor(X.age)+1)} ปีย่าง) · ดาวอายุ ${NM[AK]} (เกิดวัน${WDN[X.wd]}) · ดาวปี พฤหัสบดี · ดาวเดือน อาทิตย์ · ดาววัน จันทร์</p>`)+
card(O,'chart','ลัคนาจรตลอดชีวิต (อายุ ๑–๙๖ ปี)',lg+'<p class="note">แต่ละช่องคือหนึ่งปี เขียว = ลัคนาจรไม่ถูกดาวร้ายเดิมทับ เล็ง หรือขนาบ · ส้ม = ถูก ๑ ทาง · แดง = ถูกตั้งแต่ ๒ ทาง หรือเข้าราศีมรณะร่วมด้วย เป็นปีที่ข้อ ๑ ข้อ ๒ ฝั่งลัคนาจรเข้าเกณฑ์ ต้องดูดาวจรประกอบอีกชั้น ชี้ที่ช่องเพื่อดูราศี</p>'); }
function tJr(X){ if(!X.TP) return '<p class="note">ไม่มีข้อมูลดาวจร</p>'; const E=eval5(X,X.T,X.TP), lv=lvOf(E.score), mk={}; mk[X.L]=A; mk[E.PL]=Y; mk[marana(X.L,X.N).ms]=B;
const bars=`<svg viewBox="0 0 660 150" class="dv0svg">${E.r.map((x,i)=>{ const y=14+i*26, w=x.w*440, c=x.w>=1?B:x.w>=.6?O:x.w>0?Y:G; return `<text x="0" y="${y+13}" font-size="11.5" fill="currentColor">${td(x.n)}. ${x.t.replace('เข้าเกณฑ์','')}</text><rect x="210" y="${y}" width="440" height="18" rx="9" fill="currentColor" fill-opacity=".07"/><rect x="210" y="${y}" width="${Math.max(4,w)}" height="18" rx="9" fill="${c}"/><text x="${214+Math.max(4,w)}" y="${y+13}" font-size="11" fill="currentColor">${td(x.w.toFixed(1))}</text>`; }).join('')}</svg>`;
const adv={1:'ระวังอุบัติเหตุ การเดินทาง และของมีคม ใจเย็นในการขับขี่',2:'ดูแลสุขภาพพื้นฐาน ตรวจร่างกายตามนัด ไม่ฝืนร่างกาย',3:'ช่วงดาวเสวยอายุถูกกระทบ ระวังโรคเรื้อรังกำเริบ พักผ่อนให้พอ',4:'ดาวอายุถูกกระทบ ลดความเสี่ยงที่ไม่จำเป็น',5:'ช่วงปี เดือน วันเข้าเกณฑ์ ควรรอบคอบเป็นพิเศษในวันที่จันทร์จรเข้าเกณฑ์'};
return `<div class="dv0hero" style="--c:${lv[1]}">${ic(E.score>=4?'warn':'shield',lv[1],40)}<div><b>ดวงจร ${fd(X.T)} · ${lv[0]}</b><span>อายุ ${td(E.yIn)} ปีย่าง · ลัคนาจรราศี${SN[E.PL]} · ดาวเสวยอายุ${NM[E.D]} · ดาวอายุ${NM[E.AK]}</span><div class="dv0bar"><i style="width:${E.score/5*100}%;background:${lv[1]}"></i></div><span>เข้าเกณฑ์เต็ม ${td(E.score)} จาก ๕ ข้อ (น้ำหนักรวม ${td(E.wsum.toFixed(1))})</span></div></div>`+
`<div class="dv0two"><div>${card(GD,'orbit','ดวงเดิม (ทึบ) กับดาวจร (โปร่ง)',`<div class="dv0wb">${wheel(X,X.TP,E.PL,mk)}</div><p class="note">ฟ้า = ลัคนาเดิม · เหลือง = ลัคนาจร (ลจ) · แดง = ราศีมรณะของลัคนา</p>`)}</div><div>${card(P,'chart','น้ำหนักของแต่ละเกณฑ์',bars+'<p class="note">ทับ เล็ง ขนาบ หรือเข้าราศีมรณะ = ๑ นับว่าเข้าเกณฑ์เต็ม · โยค = ๐.๖ · ตรีโกณ = ๐.๕ นับเป็นบางส่วน · ข้อ ๕ ต้องเข้าเต็มทั้งดาวปี เดือน และวัน</p>')}</div></div>`+
card(O,'list','รายละเอียดทีละข้อ พร้อมคำแนะนำ',E.r.map(x=>{ const c=x.s?B:x.w>0?Y:G; return `<div class="dv0q" style="--c:${c}"><div class="h">${ic(x.w>0?'warn':'ok',c,18)}<span>${td(x.n)}. ${x.t}</span>${tag(x.s?'เข้าเกณฑ์เต็ม':x.w>0?'เข้าบางส่วน':'ไม่เข้า',c)}</div>${x.h.length?'<ul class="dv0ck">'+x.h.slice(0,8).map(h=>`<li>${ic('orbit',c,14)}<span>${h.t}</span></li>`).join('')+'</ul>':'<p class="note">ไม่มีดาวจรสัมพันธ์ตามเกณฑ์</p>'}${x.w>0?`<p>${adv[x.n]}</p>`:''}</div>`; }).join(''))+
`<div class="dv0verdict" style="--c:${lv[1]}">${ic('lotus',lv[1],22)}<div><b>คำพยากรณ์</b><p>${E.score>=5?'หลายเกณฑ์ทับซ้อนกัน เป็นช่วงที่ตำราให้เฝ้าระวังสุขภาพและความปลอดภัยเป็นพิเศษ ไม่ควรประมาท ควรตรวจสุขภาพ เลี่ยงความเสี่ยง และทำบุญตามข้อยกเว้นข้อ ๒':E.score>=4?'มีหลายเกณฑ์เข้า แต่ยังไม่ครบหนัก ควรระมัดระวังเรื่องสุขภาพ การเดินทาง และใช้ชีวิตไม่ประมาท':E.score>=3?'เข้าเกณฑ์บางข้อ เป็นเคราะห์ระดับเบา ใช้ชีวิตตามปกติด้วยความไม่ประมาท':'ช่วงนี้ดาวจรไม่ค่อยกระทบเกณฑ์อายุ ชีวิตค่อนข้างปลอดโปร่ง'}</p><p class="note">ตามตำรา ต้องเข้าครบทั้ง ๕ ข้อจึงถือว่าเป็นช่วงสำคัญ และยังมีข้อยกเว้นเรื่องดาวอายุดีเด่นและบุญกุศล</p></div></div>`; }
function scan(X,done){ const t0=new Date(X.T); t0.setHours(12,0,0,0); const n=366*3, out=[]; let i=0;
const step=()=>{ const lim=performance.now()+14; while(i<n&&performance.now()<lim){ const t=new Date(+t0+i*864e5); try{ const TP=full(t,chartAt(t,X.lat,X.lon).pos), E=eval5(X,t,TP); out.push({t,s:E.score,r:E.r.map(x=>x.s?1:0),d:E.r[4].parts[2].w}); }catch(e){ out.push({t,s:0,r:[0,0,0,0,0],d:0}); } i++; }
if(i<n) setTimeout(step,0); else done(out); }; step(); }
function tScan(X){ const key=Math.floor(+X.T/864e5)+'|'+(+X.bt); if(SCK!==key||!SC){ if(SCK!==key){ SCK=key; SC=null; scan(X,o=>{ if(SCK===key){ SC=o; render(); } }); } return card(A,'clock','กำลังคำนวณ ๓ ปีข้างหน้า…','<p class="note">ตรวจทั้ง ๕ เกณฑ์ทุกวัน ใช้เวลาไม่กี่วินาที</p>'); }
const D=SC, W=640, x=i=>10+i/(D.length-1)*W, y=v=>110-v/5*100;
let g=`<svg viewBox="0 0 660 150" class="dv0svg"><rect x="10" y="${y(5)-4}" width="${W}" height="8" fill="${B}" fill-opacity=".12"/><rect x="10" y="${y(4)-4}" width="${W}" height="8" fill="${O}" fill-opacity=".1"/>`;
[1,2,3,4,5].forEach(v=>g+=`<path d="M10 ${y(v)}H650" stroke="currentColor" stroke-opacity=".08"/><text x="652" y="${y(v)+3}" font-size="9" fill="currentColor" opacity=".6">${td(v)}</text>`);
g+=`<path d="M${D.map((p,i)=>`${x(i).toFixed(1)} ${y(p.s).toFixed(1)}`).join('L')}" fill="none" stroke="${A}" stroke-width="1.2" stroke-linejoin="round"/>`;
D.forEach((p,i)=>{ if(p.t.getDate()===1){ g+=`<path d="M${x(i)} 110v5" stroke="currentColor" stroke-opacity=".4"/>`; if(p.t.getMonth()%3===0) g+=`<text x="${x(i)}" y="128" font-size="9" text-anchor="middle" fill="currentColor" opacity=".7">${MO[p.t.getMonth()]}${td(String(p.t.getFullYear()+543).slice(2))}</text>`; } if(p.s>=5) g+=`<circle cx="${x(i)}" cy="${y(p.s)}" r="2.2" fill="${B}"/>`; });
g+=`<text x="10" y="145" font-size="10" fill="currentColor" opacity=".75">เส้นสีฟ้า = จำนวนข้อที่เข้าเกณฑ์เต็มในแต่ละวัน · จุดแดง = วันที่เข้าครบ ๕ ข้อ</text></svg>`;
const per=[]; let cur=null; D.forEach(p=>{ if(p.s>=4){ if(!cur){ cur={a:p.t,b:p.t,mx:p.s,pk:p}; per.push(cur); } else { cur.b=p.t; if(p.s>cur.mx){ cur.mx=p.s; cur.pk=p; } } } else cur=null; });
const top=per.sort((a,b)=>b.mx-a.mx).slice(0,8).sort((a,b)=>a.a-b.a);
const avg=D.reduce((s,p)=>s+p.s,0)/D.length, hi=D.filter(p=>p.s>=5).length;
const months=Array.from({length:36},(_,k)=>{ const s=D.slice(k*30,k*30+30); return s.length?s.reduce((a,p)=>a+p.s,0)/s.length:0; });
const hm=`<div class="dv0hm">${months.map((v,k)=>{ const t=D[Math.min(D.length-1,k*30)].t, c=lvOf(Math.round(v))[1]; return `<div style="--c:${c};opacity:${.35+Math.min(1,v/3)*.65}" title="${MO[t.getMonth()]} ${t.getFullYear()+543}: เฉลี่ย ${v.toFixed(2)}"><b>${MO[t.getMonth()]}</b><span>${td(String(t.getFullYear()+543).slice(2))}</span></div>`; }).join('')}</div>`;
return card(A,'chart',`จำนวนข้อที่เข้าเกณฑ์เต็ม รายวัน ๓ ปี นับจาก ${fd(D[0].t)}`,g)+`<div class="dv0two"><div>${card(P,'grid','ภาพรวมรายเดือน',hm+'<p class="note">สีตามจำนวนข้อเฉลี่ยของเดือน เขียวปกติ เหลืองปานกลาง ส้มระวัง แดงเฝ้าระวัง</p>')}</div><div>${card(GD,'star','สรุป',`${kv('เฉลี่ยเข้าเกณฑ์เต็ม',td(avg.toFixed(2))+' ข้อต่อวัน')}${kv('วันที่เข้าครบ ๕ ข้อ',td(hi)+' วัน')}${kv('ช่วงที่เข้า ๔ ข้อขึ้นไป',td(per.length)+' ช่วง')}<p class="note">ตำราให้ตรวจเป็นช่วงละ ๓–๖ เดือน วันที่จันทร์จรเข้าเกณฑ์ในช่วงหนักคือวันที่ต้องระวังที่สุด</p>`)}</div></div>`+
card(B,'warn','ช่วงที่ควรเฝ้าระวังสุขภาพและความปลอดภัย',top.length?top.map(p=>{ const lv=lvOf(p.mx), rr=p.pk.r.map((w,i)=>w>0?td(i+1):'').filter(Boolean).join(' '); return `<div class="dv0q" style="--c:${lv[1]}"><div class="h">${ic('warn',lv[1],18)}<span>${fd(p.a)}${+p.b!==+p.a?' – '+fd(p.b):''}</span>${tag(lv[0],lv[1])}</div><p>เข้าเกณฑ์เต็ม ${td(p.mx)} ข้อ (ข้อ ${rr}) · วันที่หนักสุด ${fd(p.pk.t)}</p><p>ควรตรวจสุขภาพ เลี่ยงการเดินทางเสี่ยงและงานอันตราย ใจเย็น และทำบุญตามกำลัง</p></div>`; }).join(''):'<p class="note">ไม่พบช่วงที่เกณฑ์ทับซ้อนหนักใน ๓ ปีข้างหน้า</p>')+'<p class="note">โหมดนี้ไม่ทำนายวันตาย แสดงเพียงช่วงที่หลักเกณฑ์ในตำราทับซ้อนกัน เพื่อเตือนให้ไม่ประมาท ความเชื่อทางโหราศาสตร์ไม่ใช่การวินิจฉัยทางการแพทย์</p>'; }
