['SA','MA','RA'].filter(z=>z!==k).forEach(z=>{ if(P[z]!=null&&sg(P[z])===s){ sc-=1; why.push(`ถูก${PN[K2N[z]]}กุม`); } }); ['JU','VE'].filter(z=>z!==k).forEach(z=>{ if(P[z]!=null&&sg(P[z])===s){ sc+=1; why.push(`${PN[K2N[z]]}กุมช่วย`); } });
