if(!document.getElementById('pc342css')){ const st=document.createElement('style'); st.id='pc342css'; st.textContent=CSS+'#pc342Out .pc2two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 10px}#pc342Out .pc2three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 10px}#pc342Out .pc2wb{display:flex;flex-direction:column;align-items:center}#pc342Out svg.pc2svg.sq{max-width:330px}#pc342Out .pc2q .h span{flex:1}#pc342Out .pc2q .h span.pc2t{flex:none}#pc342Out .pc2hero{display:flex;gap:14px;align-items:center;border:1px solid var(--c);border-radius:16px;padding:12px 14px;margin:8px 0;background:color-mix(in srgb,var(--c) 10%,transparent)}#pc342Out .pc2hero>div{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}#pc342Out .pc2hero b{font-size:16px;color:var(--c)}#pc342Out .pc2hero span{font-size:12.5px;opacity:.85}#pc342Out .pc2r4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}#pc342Out .pc2r4 span{display:flex;flex-direction:column;align-items:center;border:1px solid var(--line);border-radius:12px;padding:6px 2px}#pc342Out .pc2r4 small{font-size:11px;opacity:.7}#pc342Out .pc2r4 b{font-size:20px;color:var(--gold)}#pc342Out .pc2big{font-size:34px;font-weight:700;color:var(--gold);text-align:center}#pc342Out .pc2ch{display:flex;flex-wrap:wrap;gap:4px;justify-content:center;font-size:12px}#pc342Out .pc2ch span{display:inline-flex;align-items:center;gap:3px;border:1px solid var(--line);border-radius:999px;padding:2px 6px}#pc342Out .pc2g7 .r,#pc342Out .pc2row{display:grid;grid-template-columns:68px repeat(7,minmax(0,1fr));gap:4px;align-items:stretch;margin:4px 0}#pc342Out .pc2g7 .r>b,#pc342Out .pc2row>b{font-size:12px;display:flex;align-items:center}#pc342Out .pc2g7 span,#pc342Out .pc2row span{display:flex;flex-direction:column;align-items:center;border:1px solid var(--line);border-radius:10px;padding:4px 1px;text-align:center;min-width:0}#pc342Out .pc2g7 span.mid,#pc342Out .pc2row span.mid{border-color:var(--gold);background:color-mix(in srgb,var(--gold) 10%,transparent)}#pc342Out .pc2g7 span.hl{outline:2px solid #2bb38f;background:rgba(43,179,143,.18)}#pc342Out .pc2g7 em{font-style:normal;font-size:19px;font-weight:700}#pc342Out .pc2g7 i,#pc342Out .pc2row i{font-style:normal;font-size:10.5px;opacity:.85;word-break:break-word}#pc342Out .pc2row small{font-size:9px;opacity:.65;line-height:1.2}#pc342Out .pc2tb td.w{white-space:normal;min-width:170px}@media(max-width:760px){#pc342Out .pc2two,#pc342Out .pc2three{grid-template-columns:minmax(0,1fr)}#pc342Out .pc2g7 .r,#pc342Out .pc2row{grid-template-columns:44px repeat(7,minmax(0,1fr));gap:2px}#pc342Out .pc2row small{display:none}#pc342Out .pc2g7 i,#pc342Out .pc2row i{font-size:9px}}'; document.head.appendChild(st); }
const TABS=[['rule','book','หลักการ'],['pichai','clock','ดวงพิชัยสงคราม'],['lak','star','ฤกษ์และหลัก'],['lek','grid','เลข ๗ ตัว'],['jr','wheel','ดวงจร']];
