for(let i=0;i<108;i++){ const [x1,y1]=pt(R2,i*10/3),[x2,y2]=pt(R2-(i%9===0?36:8),i*10/3); s+=`<path d="M${x1} ${y1}L${x2} ${y2}" stroke="currentColor" stroke-opacity="${i%9===0?.45:.15}"/>`; }
