document.addEventListener('click',ev=>{ const e=ev.target.closest&&ev.target.closest('#fr343Out [data-frt],#fr343Out [data-frp],#fr343Out [data-frg]'); if(!e) return; const d=e.dataset;
if(d.frt){ TAB=d.frt; render(); document.getElementById('fr343P').scrollIntoView({block:'start',behavior:'smooth'}); return; }
if(d.frp){ PUR=d.frp; render(); return; }
if(d.frg){ try{ stopLive(false); }catch(_){} try{ setTransit(new Date(+d.frg)); }catch(_){} TAB='now'; setTimeout(render,300); } });
return {render,ctx,pos,check};
