if(!document.getElementById('pb348css')){ const st=document.createElement('style'); st.id='pb348css'; const O2='#pb348Out '; st.textContent=[`.pb8H{display:flex;align-items:center;gap:8px;margin:0 0 4px;font-size:16px;font-weight:500;color:var(--gold)}`,`.pb8tabs{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:6px;margin:10px 0}`,`.pb8tabs button{display:flex;flex-direction:column;align-items:center;gap:3px;padding:8px 4px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--ink);font:inherit;font-size:12.5px;cursor:pointer;width:auto!important}`,`.pb8tabs button.on{border-color:var(--gold);color:var(--gold);background:color-mix(in srgb,var(--gold) 10%,var(--panel))}`,`.pb8c{border:1px solid var(--line);border-left:4px solid;border-radius:14px;padding:9px 12px;margin:8px 0;background:var(--panel);font-size:13.5px;line-height:1.6;min-width:0}`,`.pb8c h4{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:0 0 6px;font-size:14.5px;font-weight:500}`,`.pb8c p{margin:4px 0}`,`.pb8t{display:inline-block;padding:0 8px;border-radius:999px;border:1px solid var(--c);color:var(--c);font-size:11.5px;line-height:1.6;white-space:nowrap}`,`.pb8pl{display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:50%;background:var(--c);color:#fff;font-size:11.5px;font-weight:600;vertical-align:middle}`,`.pb8w,.pb8tw{overflow-x:auto;margin:6px 0}`,`svg.pb8svg{width:100%!important;height:auto!important;max-width:680px;display:block;color:var(--ink)}`,`.pb8w svg.pb8svg{min-width:520px}`,`svg.pb8svg.sq{max-width:360px;margin:auto}`,`.pb8lg{display:flex;flex-wrap:wrap;gap:4px;justify-content:center;margin:4px 0}`,`.pb8tb{border-collapse:collapse;width:100%;font-size:12.5px}`,`.pb8tb th,.pb8tb td{padding:5px 6px;border-bottom:1px solid var(--line);text-align:left;vertical-align:middle;white-space:nowrap}`,`.pb8tb td.sm{white-space:normal;min-width:200px}`,`.pb8tb th{font-weight:500;color:var(--muted)}`,`.pb8g{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:6px 10px;margin:6px 0}`,`.pb8q{border:1px solid var(--line);border-top:3px solid var(--c);border-radius:12px;padding:8px 10px;background:color-mix(in srgb,var(--c) 6%,var(--panel));font-size:13px}.pb8qh{display:flex;gap:8px;align-items:center}.pb8qh b{display:block;color:var(--c);font-size:14.5px}.pb8qh small{opacity:.75}`,`.pb8days{display:grid;grid-template-columns:repeat(auto-fill,minmax(100px,1fr));gap:5px;margin:6px 0}.pb8days>div{display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px;border-radius:10px;border:1px solid color-mix(in srgb,var(--c) 45%,transparent);background:color-mix(in srgb,var(--c) 8%,transparent);font-size:12px}.pb8days small{opacity:.8}`,`.sm{font-size:12.5px;opacity:.9}`,`.pb8two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 12px;align-items:start}`,`.pb8kv{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:4px 0;border-bottom:1px dashed var(--line);font-size:12.5px}`,`.pb8bar{display:flex;height:9px;border-radius:6px;background:rgba(127,127,127,.15);overflow:hidden;margin:6px 0}.pb8bar i{display:block;height:100%}`,`.pb8m{display:grid;grid-template-columns:auto 1fr;gap:2px 12px;align-items:center;margin:4px 0 8px}.pb8m>div:first-child{grid-row:span 2}.pb8m small{display:block;font-size:11px;opacity:.75}.pb8m b{font-size:26px;font-weight:600}.pb8m .pb8lg{justify-content:flex-start}`,`.pb8it{display:flex;gap:8px;align-items:flex-start;padding:6px 8px;border-radius:10px;border:1px solid color-mix(in srgb,var(--c) 35%,transparent);background:color-mix(in srgb,var(--c) 7%,transparent)}.pb8it p{margin:0}`,`.pb8p{border:1px solid color-mix(in srgb,var(--c) 40%,transparent);border-left:4px solid var(--c);border-radius:12px;padding:7px 10px;margin:6px 0;background:color-mix(in srgb,var(--c) 6%,transparent)}.pb8p h5{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:0 0 4px;font-size:14px;font-weight:600}.pb8p h5 small{font-weight:400;opacity:.75}`,`.pb8ln{display:flex;gap:6px;align-items:flex-start;font-size:13px;line-height:1.55;padding:2px 0}.pb8ln svg{margin-top:3px}`,`.pb8sw{display:flex;flex-wrap:wrap;gap:5px;margin:6px 0}.pb8sw button{padding:4px 12px;border-radius:999px;border:1px solid var(--c,var(--line));background:transparent;color:var(--ink);font:inherit;font-size:12.5px;cursor:pointer;width:auto!important}.pb8sw button.on{border-color:var(--gold);color:var(--gold);background:color-mix(in srgb,var(--gold) 12%,transparent)}`,`.pb8go{padding:2px 10px;border-radius:999px;border:1px solid var(--gold);background:transparent;color:var(--gold);font:inherit;font-size:12px;cursor:pointer;width:auto!important}`,`.pb8nt{font-size:11.5px;opacity:.7;margin-top:8px}`].map(r=>r.split('}').filter(x=>x.trim()).map(x=>O2+x.trim()+'}').join('')).join('')+`@media(max-width:760px){${O2}.pb8two{grid-template-columns:minmax(0,1fr)}}`; document.head.appendChild(st); }
return {render,scan};
