const p2=KK.filter(k=>MAL(k)&&h(k)===2), p12=KK.filter(k=>MAL(k)&&h(k)===12), b2=KK.filter(k=>BEN[k]&&h(k)===2), b12=KK.filter(k=>BEN[k]&&h(k)===12);
if(p2.length&&p12.length) R.push(['r','บาปเคราะห์ขนาบลัคนา',`${p2.map(k=>TN[k]).join(' ')} อยู่หน้า ${p12.map(k=>TN[k]).join(' ')} อยู่หลัง ชีวิตมีอุปสรรคเดือดร้อนไม่สร่าง`]);
if(b2.length&&b12.length) R.push(['g','ศุภเคราะห์ขนาบลัคนา',`${b2.map(k=>TN[k]).join(' ')} กับ ${b12.map(k=>TN[k]).join(' ')} ได้ผู้อุปถัมภ์ค้ำชู ตกน้ำไม่ไหล ตกไฟไม่ไหม้`]);
if(p2.length>=2) R.push(['r','บาปเคราะห์นำหน้าลัคน์หลายดวง',`${p2.map(k=>TN[k]).join(' ')} อยู่ภพที่ ๒ ชีวิตมีอุปสรรคมาก`]);
