for(let i=0;i<12;i++){ for(let j=i+1;j<12;j++){ const a=LRD[i], b=LRD[j]; if(a===b||P[a]==null||P[b]==null) continue; if(sg(P[a])===j&&sg(P[b])===i){ const hi=cnt(L,i), hj=cnt(L,j); if(DU.includes(hi)!==DU.includes(hj)) R.push(['y','แลกเรือนกับทุสถาน',`${TN[a]}กับ${TN[b]}แลกเรือนกัน (ภพ${HN[hi-1]} กับ ภพ${HN[hj-1]}) ผลไม่ดีของทุสถานไหลเข้ามา`]); } } }
