const card=(c,icn,t,b)=>`<div class="rk5c" style="border-left-color:${c}"><h4>${ic(icn,c)} ${t}</h4>${b}</div>`;
const nrm=x=>((x%360)+360)%360, sg=x=>Math.floor(nrm(x)/30), cnt=(a,b)=>((b-a)%12+12)%12+1;
const nak=lon=>{ const f=nrm(lon)/(360/27), i=Math.floor(f); return {i,n:i+1,pada:Math.floor((f-i)*4)+1}; };
function padaSev(n,p){ const m=(n-1)%9; if(m===2) return p===1?[3,'เอกตรีน (บาทแรกโจโร ขาดอยู่ราศีไฟ)']:[2.5,'บาทโจโร ขาดอยู่ราศีดิน']; if(m===6) return p===4?[3,'ตรีนเอก (บาทท้ายเพชฌฆาต ขาดอยู่ราศีน้ำ)']:[2.5,'บาทเพชฌฆาต ขาดอยู่ราศีลม']; if(m===4) return [2,'นิทุบาท (เทศาตรี ฤกษ์อกแตก)']; if(m===0&&p===1) return [1,'บาทต้นทลิทโท ปลายขาดของกองฤกษ์']; if(m===8&&p===4) return [1,'บาทท้ายสมโณ ปลายขาดของกองฤกษ์']; return [0,'บาทดี']; }
function triPis(lon){ const s=sg(lon), t=Math.floor((nrm(lon)-s*30)/10)+1; const P1=[0,5,8,11], P2=[1,4,6,10], P3=[2,3,7,9]; if(P1.includes(s)&&t===1) return 'พิษนาค'; if(P2.includes(s)&&t===2) return 'พิษครุฑ (เล็บครุฑ)'; if(P3.includes(s)&&t===3) return 'พิษสุนัข (เขี้ยวหมู)'; return ''; }
const TN={1:'อาทิตย์',2:'จันทร์',3:'อังคาร',4:'พุธ',5:'พฤหัสบดี',6:'ศุกร์',7:'เสาร์',8:'ราหู'};
