[[-a,-a,-1,-1],[a,-a,1,-1],[-a,a,-1,1],[a,a,1,1]].forEach(([x,y,dx,dy])=>{ const e=R/Math.SQRT2; g+=`<line x1="${cx+x}" y1="${cy+y}" x2="${cx+dx*e}" y2="${cy+dy*e}" stroke="currentColor" stroke-opacity=".3"/>`; });
[[-a,-R],[a,-R]].forEach(([x])=>{ const yy=Math.sqrt(R*R-x*x); g+=`<line x1="${cx+x}" y1="${cy-yy}" x2="${cx+x}" y2="${cy+yy}" stroke="currentColor" stroke-opacity=".3"/><line x1="${cx-yy}" y1="${cy+x}" x2="${cx+yy}" y2="${cy+x}" stroke="currentColor" stroke-opacity=".3"/>`; });
(o.hi||[]).forEach(([s,c])=>{ const [x,y]=PP[s]; g+=`<circle cx="${cx+x*R}" cy="${cy+y*R}" r="30" fill="${c}" fill-opacity=".16"/>`; });
SN.forEach((n,s)=>{ const [x,y]=PP[s]; g+=`<text x="${cx+x*R*1.33}" y="${cy+y*R*1.33+4}" font-size="11" text-anchor="middle" fill="currentColor" opacity="${o.L===s?1:.6}" font-weight="${o.L===s?700:400}">${n}${o.L===s?' (ลั)':''}</text>`; });
