const now=Date.now(); if(now>=+t0&&now<=+t1) g+=`<line x1="${xs(now)}" y1="${tp}" x2="${xs(now)}" y2="${H-bt}" stroke="${B}" stroke-width="1.5"/><text x="${xs(now)+3}" y="${tp+9}" font-size="9.5" fill="${B}">วันนี้</text>`;
