const t0=+E.reduce((m,e)=>e.a<m?e.a:m,E[0]?E[0].a:now), t1=+E.reduce((m,e)=>e.b>m?e.b:m,now), W=700, l=92, xs=t=>l+(Math.max(t0,Math.min(t1,t))-t0)/(t1-t0)*(W-l-8), sy=SYS==='B'?['T','L']:[SYS]; let g='';
sy.forEach((s,r)=>{ const y=10+r*46; g+=`<text x="2" y="${y+20}" font-size="10.5" fill="currentColor">${s==='L'?'ลาหิรี':'สุริยยาตร์'}</text>`; E.filter(e=>e.sys===s).forEach(e=>{ const x=xs(+e.a), w=Math.max(2,xs(+e.b)-x); g+=`<rect x="${x}" y="${y}" width="${w}" height="30" rx="5" fill="${e.J.vd[1]}" opacity=".75" stroke="var(--panel,#fff)" stroke-width="1"/>${w>26?`<text x="${x+w/2}" y="${y+13}" font-size="9.5" text-anchor="middle" fill="#fff" font-weight="700">${HN[e.J.h-1]}</text><text x="${x+w/2}" y="${y+25}" font-size="8.5" text-anchor="middle" fill="#fff">${SN[e.s]}</text>`:''}`; }); });
const span=(t1-t0)/864e5/365.25, stp=span>45?10:span>20?5:span>8?2:1, Hh=14+sy.length*46; for(let yv=0;yv<=span;yv+=stp){ const t=t0+yv*365.25*864e5; g+=`<line x1="${xs(t)}" y1="4" x2="${xs(t)}" y2="${Hh}" stroke="currentColor" stroke-opacity=".12"/><text x="${xs(t)}" y="${Hh+12}" font-size="9.5" text-anchor="middle" fill="currentColor" opacity=".65">${td(new Date(t).getFullYear()+543)}</text>`; }
