const YR=365.2425*864e5, VL=['KE','VE','SU','MO','MA','RA','JU','SA','ME'], VY={KE:7,VE:20,SU:6,MO:10,MA:7,RA:18,JU:16,SA:19,ME:17};
function vim(X){ const mo=nrm(X.N.MO), nl=360/27, ni=Math.floor(mo/nl), fr=(mo%nl)/nl; let i=ni%9, t=+X.bt-fr*VY[VL[i]]*YR; const R=[];
while(t<+X.bt+110*YR){ const k=VL[i], d=VY[k]*YR, sub=[]; let s=t; for(let m=0;m<9;m++){ const a=VL[(i+m)%9], dd=d*VY[a]/120; sub.push({k:a,a:new Date(s),b:new Date(s+dd)}); s+=dd; } R.push({k,a:new Date(t),b:new Date(t+d),sub}); t+=d; i=(i+1)%9; } return R; }
const TQ=['SU','MO','MA','ME','SA','JU','RA','VE'], TY={SU:6,MO:15,MA:8,ME:17,SA:10,JU:19,RA:12,VE:21};
function dayLord(bt){ const d=new Date(+bt-(bt.getHours()<6?864e5:0)), w=d.getDay(); if(w===3&&bt.getHours()>=18) return 'RA'; return ['SU','MO','MA','ME','JU','VE','SA'][w]; }
