const h2=(L+1)%12, benOn2=['JU','VE'].filter(k=>N[k]!=null&&[1,5,7,9].includes(cnt(h2,sg(N[k])))), malOn2=['SA','MA'].filter(k=>N[k]!=null&&[1,7].includes(cnt(h2,sg(N[k]))));
