if(b&&!same) s+=`<h4 style="display:flex;gap:6px;align-items:center;margin:10px 0 4px">${ic('people',P)} ดาวที่อยู่ร่วมกับตนุเศษ (ราศี${SN[b.si]})</h4>${coTbl(b)}`;
