const SEG={}; function segs(t0,hours,X){ const key=Math.floor(+t0/6e4)+'|'+hours+'|'+X.lat+'|'+X.lon; if(SEG[key]) return SEG[key]; const step=2*6e4, end=+t0+hours*36e5, id=t=>{ const l=LA(new Date(t),X); return l==null?-1:Math.floor(l/(10/3)); };
const out=[]; let a=+t0, ia=id(a); for(let t=a+step;t<=end+step;t+=step){ const it=id(t); if(it!==ia){ let lo=t-step, hi=t; for(let q=0;q<12;q++){ const m=(lo+hi)/2; if(id(m)===ia) lo=m; else hi=m; } out.push({a:new Date(a),b:new Date(hi),i:ia}); a=hi; ia=it; } }
out.push({a:new Date(a),b:new Date(end),i:ia,open:true}); out.forEach(o=>{ const I2=info(o.i*(10/3)+1e-6); o.inf=I2; }); SEG[key]=out; if(Object.keys(SEG).length>12) delete SEG[Object.keys(SEG)[0]]; return out; }
