function tTbl(){ const t1=`<div class="kh8tw"><table class="kh8tb"><tr><th>ตำแหน่ง</th><th>ภพ</th><th>ความหมาย</th></tr>${[[1,'ตัวบ้านเกิด'],[2,'หน้าบ้าน'],[7,'ตรงข้ามบ้าน'],[12,'หลังบ้าน']].map(([h,m])=>`<tr><td>${ic(ZONE[h][1]==='home'?'home':'map',GO,16)} ${m}</td><td>${h===1?'ลัคนา':HN[h-1]}</td><td>${h===1?'ตัวบ้านที่เกิด':m}</td></tr>`).join('')}</table></div>`;
const t2=`<div class="kh8tw"><table class="kh8tb"><tr><th>ดาวในตำแหน่งรอบบ้าน</th><th>สิ่งที่อยู่ตรงนั้น</th></tr>${[['ME','river','แม่น้ำ ลำคลอง'],['VE','river','แม่น้ำ ลำคลอง และกล้วย อ้อย'],['JU','temple','วัด โรงพยาบาล ศาลยุติธรรม โรงเรียน ศาลเจ้า'],['RA','lantern','บ้านคนจีน'],['SA','tree','ต้นไม้ใหญ่ ต้นโพธิ์ ต้นไทร'],['KE','vase','ของเก่าแก่โบราณ']].map(([k,i,m])=>`<tr><td>${pl(k)} ${TN[k]}</td><td>${ic(i,GO,18)} ${m}</td></tr>`).join('')}<tr><td>${pl('JU')} พฤหัสเล็งลัคนา</td><td>${ic('child',P,18)} ยกลูกให้พระ หรือให้ผู้ใหญ่เลี้ยง</td></tr><tr><td>${pl('KE')} เกตุอยู่ศุภะ</td><td>${ic('buddha',GO,18)} บ้านมีพระพุทธรูปเก่าแก่ เครื่องกังไสลายคราม</td></tr><tr><td>${pl('ME')} พุธอยู่พันธุ ราศีธาตุน้ำ</td><td>${ic('water',A,18)} ที่อยู่อาศัยติดน้ำ</td></tr></table></div>`;
const t3=`<div class="kh8tw"><table class="kh8tb"><tr><th>ดาว</th><th>สีปาน</th></tr>${[['SU MA','ปานแดง','#e0453a'],['SA RA','ปานดำหรือน้ำตาล','#6b4a2e'],['MO ME JU VE','ปานขาว','#f2efe6']].map(([ks,t,c])=>`<tr><td>${ks.split(' ').map(k=>pl(k)).join(' ')}</td><td><span class="bh9dot" style="background:${c}"></span> ${t}</td></tr>`).join('')}</table></div><div class="kh8tw"><table class="kh8tb"><tr><th>ราศี</th><th>บริเวณ</th><th>ด้าน</th></tr>${SN.map((s,i)=>`<tr><td>${s}</td><td>${BODY[i]}</td><td>${i%2===0?'ซ้าย':'ขวา'}</td></tr>`).join('')}</table></div>`;
return card(GO,'map','ตำแหน่งรอบบ้าน',t1)+card(GO,'home','ดาวกับสิ่งรอบบ้าน',t2)+card(B,'body','ฝี ไฝ ปาน แผล: สีและบริเวณ',t3); }
function tHow(){ const st=[['wheel','นับภพจากลัคนา','ลัคนาคือตัวบ้านเกิด ภพกดุมภะ (๒) คือหน้าบ้าน ภพปัตนิ (๗) คือตรงข้ามบ้าน ภพวินาศ (๑๒) คือหลังบ้าน'],['map','ดูดาวในตำแหน่งรอบบ้าน','ดาวที่อยู่ในสี่ตำแหน่งนี้บอกสิ่งที่อยู่ตรงนั้น เช่น เสาร์คือต้นไม้ใหญ่ ราหูคือบ้านคนจีน พฤหัสคือวัด โรงเรียน โรงพยาบาล'],['child','เกณฑ์พิเศษ','พฤหัสเล็งลัคนา ยกลูกให้พระหรือผู้ใหญ่ · เกตุอยู่ศุภะ มีพระพุทธรูปเก่า · พุธอยู่พันธุราศีน้ำ บ้านติดน้ำ'],['body','หาดาวตำหนิ','ใช้เจ้าเรือนอริ (ภพ ๖) ตนุลัคน์ (เจ้าเรือนลัคนา) และดาวที่อยู่ในลัคนา'],['dot','ดูสีปาน','๑ ๓ ปานแดง · ๗ ๘ ปานดำหรือน้ำตาล · ๒ ๔ ๕ ๖ ปานขาว'],['user','ดูบริเวณ','ดาวตำหนิอยู่ราศีไหน ตำหนิอยู่ส่วนนั้นของร่างกาย และจันทร์อยู่ราศีไหนมีตำหนิตรงนั้นเสมอ'],['orbit','ดวงจรและดวง ณ เวลานี้','ดาวจรเข้าตำแหน่งรอบบ้านของดวงเดิมบอกเรื่องที่เข้ามาในช่วงนั้น · ดวง ณ เวลาที่ถามใช้ดูทำเลสถานที่']];
return card(GD,'book','หลักวิชาและวิธีคำนวณ',`<div class="bh9st">${st.map(([i,a,b],n)=>`<div><span>${td(n+1)}</span>${ic(i,GD,20)}<div><b>${a}</b><p>${b}</p></div></div>`).join('')}</div>`)+card(Y,'wn','ข้อสันนิษฐานของแอป',`<p>เจ้าเรือนใช้แบบไทย กุมภ์เป็นราหู · "ลัคนา" ในหัวข้อตำหนิ ใช้ดาวที่อยู่ร่วมราศีลัคนา · เกตุและมฤตยูไม่มีสีปานในตำรา จึงไม่นับ · ด้านซ้ายขวาของตำหนิใช้ราศีลำดับคู่เป็นซ้าย ลำดับคี่เป็นขวา ตามตารางตำหนิที่อาจารย์ส่งมาก่อนหน้า · "ใส้ตัน" เขียนเป็นไส้ติ่ง</p><p class="note">เรียบเรียงจากตารางที่อาจารย์ส่งมา</p>`); }
let TAB='nat'; const TABS=[['nat','user','ดวงเดิม'],['tr','orbit','ดวงจร เวลาเข้าเกณฑ์'],['now','now','ดวง ณ เวลานี้'],['tbl','grid','ตารางครบ'],['how','book','วิธีคำนวณ']];
