const CJ=[[['SU','MO'],'m','ใจเผื่อแผ่ เจ้าชู้'],[['SU','MA'],'g','กล้าหาญ สมบัติมาก การงานดี'],[['SU','ME'],'g','ปัญญามาก รู้ธรรม เจ้าชู้'],[['SU','JU'],'g','ผู้ใหญ่รัก สมบัติมาก ปัญญาดี'],[['SU','VE'],'m','เจ้าชู้ เจ้าเสน่ห์ ตระหนี่ บริวารน้อย'],[['SU','SA|RA'],'g','บริวารมาก มีสมบัติ'],[['MO','MA'],'b','ต้องเลี้ยงตัวเอง ยุ่งเรื่องชู้สาว'],[['MO','ME'],'g','ความรู้มาก มีสัจจะ เจ้าชู้'],[['MO','JU'],'g','เป็นที่พึ่งของผู้อื่น เครื่องอุปโภคมาก'],[['MO','VE'],'b','เจ้าชู้ ระวังผิดในคู่ครองผู้อื่น'],[['MO','SA|RA'],'b','มักมีเรื่องเศร้า ไม่ค่อยเต็มใจ'],[['MA','ME'],'b','มักเร่ร่อน ไม่เป็นหลักแหล่ง'],[['MA','JU'],'g','เป็นผู้ใหญ่ รักษาสมบัติดี'],[['MA','VE'],'m','มีศิลปะดี แต่เรื่องคู่ไม่ราบรื่น เจ้าชู้'],[['MA','SA|RA'],'b','ระวังเรื่องชู้สาว คนในบ้านนำความร้อนใจ'],[['ME','JU'],'g','มียศศักดิ์ดี'],[['ME','VE'],'m','ใจอ่อน เจ้าชู้ รักความรื่นรมย์ ศิลปะ'],[['ME','SA|RA'],'b','ใจแข็ง หยาบช้า ระวังเรื่องชู้สาว'],[['JU','VE'],'g','สมบัติมาก เจริญด้วยลาภยศ'],[['JU','SA|RA'],'g','อายุยืน คู่งามแต่ใช้จ่ายมาก'],[['VE','SA|RA'],'m','อายุยืน สมบัติมาก แต่คู่ไม่ซื่อตรง']];
function rules52(N,L){ const R=[], s=k=>N[k]!=null?sg(N[k]):-9, h=k=>N[k]!=null?cnt(L,s(k)):0;
for(const [[a,b],t,x] of CJ){ const bs=b.split('|'); const hit=bs.filter(q=>s(a)===s(q)); if(hit.length) R.push([t,`${TN[a]}กุม${hit.map(q=>TN[q]).join('หรือ')}`,x]); }
if(s('MO')===L&&[3,9,11].includes(L)) R.push(['g','จันทร์กุมลัคนาในกรกฎ มังกร หรือมีน','ได้เป็นใหญ่ มีบริวารมาก']);
if(s('MA')===L&&[0,1,8,9].includes(L)) R.push(['g','อังคารกุมลัคนาในเมษ พฤษภ ธนู หรือมังกร','มีอำนาจวาสนาดี']);
if([0,1,10].includes(s('RA'))) R.push(['g','ราหูอยู่ราศีเมษ พฤษภ หรือกุมภ์','มีสมบัติมาก จะได้เป็นใหญ่']);
if(s('MO')===s('JU')&&s('JU')===s('RA')&&[0,3,6,9].includes(s('MO'))) R.push(['g','จันทร์ พฤหัสบดี ราหู อยู่ด้วยกันในราศีจร (เมษ กรกฎ ตุลย์ มังกร)','คนบูชาเคารพนับถือ']);
const jh=h('JU'); if(jh===1) R.push(['g','พฤหัสบดีกุมลัคนา (กมุทเกณฑ์)','มีความสุขนัก ชะตาคุ้มโทษ']); if(jh===4) R.push(['g','พฤหัสบดีเป็น ๔ แก่ลัคนา (ปทุมเกณฑ์)','เจริญรุ่งเรือง ปรารถนาสิ่งใดมักสำเร็จ']); if(jh===9) R.push(['g','พฤหัสบดีเป็น ๙ แก่ลัคนา (รามเกณฑ์)','แม้เกิดในตระกูลลำบากก็จะได้ดี']); if(jh===11) R.push(['g','พฤหัสบดีเป็น ๑๑ แก่ลัคนา (สิงห์เกณฑ์)','มีความสุขนัก มีคนยำเกรง']); if(jh===7) R.push(['m','พฤหัสบดีเล็งลัคนา','คู่ครองอายุมากกว่า']);
if(s('JU')===7) R.push(['g','พฤหัสบดีอยู่ราศีพิจิก','เป็นคนคมคาย รู้ทันคน']);
if(s('MA')===s('SA')&&N.MO!=null&&s('MO')===(s('MA')+6)%12) R.push(['m','อังคารกุมเสาร์ มีจันทร์เล็ง','ได้คู่กับคนทำงานใกล้ตัว']);
const mh=h('MA'); if(mh===7) R.push(['b','อังคารเล็งลัคนา','ระวังเรื่องคู่ครอง มักห่างเหิน']); if(mh===1) R.push(['m','อังคารกุมลัคนา','ปากกล้า ใจร้อน เปลี่ยนงานบ่อย']); if(mh===4) R.push(['b','อังคารเป็น ๔ แก่ลัคนา','ระวังอุบัติเหตุ']); if(mh===9) R.push(['b','อังคารเป็น ๙ แก่ลัคนา','ระวังคดีความถึงโรงศาล']);
if(N.KE!=null&&s('MA')===(s('KE')+6)%12) R.push(['b','อังคารกับเกตุเล็งกัน','ระวังชีวิตคู่ไม่ยืนยาว']);
if(s('VE')===s('MO')||s('VE')===s('RA')) R.push(['b','ศุกร์กุมจันทร์หรือราหู','ระวังคู่ครองใช้จ่ายสิ้นเปลือง']);
if(MALS.some(k=>s(k)===(s('MO')+6)%12)) R.push(['b','บาปเคราะห์เล็งจันทร์','ระวังสายตา']);
if(s('MO')===0) R.push(['g','จันทร์อยู่ราศีเมษ','ตาสวยคม หญิงได้คู่ดี']); if(s('MO')===1) R.push(['m','จันทร์อยู่ราศีพฤษภ','ตาดุ แววตาแข็ง']);
if(h('ME')===2) R.push(['b','พุธเป็น ๒ แก่ลัคนา','ใจร้อนเรื่องเงิน ระวังเดือดร้อนในครอบครัว']); if(h('ME')===7) R.push(['b','พุธเล็งลัคนา','ระวังโรคตา']);
if(h('RA')===2) R.push(['b','ราหูเป็น ๒ แก่ลัคนา',`ระวังสุขภาพฟัน${s('SA')===s('RA')?' และมีเสาร์ร่วม มักต้องละถิ่นฐาน':''}`]);
if(s('VE')===L&&s('SA')===L) R.push(['b','ลัคนากุมศุกร์กับเสาร์','ระวังโรคตา']);
const one={SU:'ชอบความสำราญ',MO:'เจ้าชู้',MA:'ชอบรสจัด',ME:'เจ้าเสน่ห์',JU:'รักความสุขสบาย',VE:'มักได้คู่ที่เคยมีคู่มาก่อน',SA:'เจ้าอารมณ์',RA:'มักมัวเมาลุ่มหลง',KE:'มักหูหนัก',UR:'ระวังโรคปอดหรือผิวหนัง'};
for(const k in one) if(N[k]!=null&&s(k)===L) R.push([k==='SA'||k==='RA'||k==='UR'?'m':'g',`${TN[k]}กุมลัคนา`,one[k]]);
return R; }
