// ── ค้นหาเวลา
function nextIngress(k,sign,from,maxDays){ const step=k==='MO'?0.25:['SU','ME','VE'].includes(k)?1:k==='MA'?2:5; let t=from, s0=sg(posAt(t)[k]); if(s0===sign) return {t:from,now:true}; const end=from+maxDays*DAY; while(t<end){ const t2=t+step*DAY; const s=sg(posH(horaOf(new Date(t2)),k)); if(s===sign){ let a=t,b=t2; for(let i=0;i<30&&b-a>6e4;i++){ const m=(a+b)/2; if(sg(posH(horaOf(new Date(m)),k))===sign) b=m; else a=m; } return {t:b}; } t=t2; } return null; }
const SUNMAX=370, PMAX={SU:370,MO:30,MA:800,ME:400,VE:600,JU:4400,SA:11000,RA:7000};
function seg(k,sign,from){ const a=nextIngress(k,sign,from,PMAX[k]); if(!a) return null; let b=null; const st=k==='MO'?0.25:k==='SU'||k==='ME'||k==='VE'?1:5; let t=a.t+60000; for(let i=0;i<4000;i++){ t+=st*DAY; if(sg(posH(horaOf(new Date(t)),k))!==sign){ b=t; break; } } return {a:a.t,b,now:a.now}; }
