const EL=['ไฟ','ดิน','ลม','น้ำ'], EC={ไฟ:'#e8743b',ดิน:'#a07a3c',ลม:'#3aa6a0',น้ำ:'#4aa3ff'}, PE={SU:'ไฟ',MA:'ไฟ',ME:'ดิน',SA:'ดิน',JU:'ลม',RA:'ลม',MO:'น้ำ',VE:'น้ำ',KE:'ลม',UR:'ไฟ'};
