const se=s=>EL[s%4];
const REL=(a,b)=>{ if(a===b) return ['s','ธาตุเดียวกัน กลมกลืน',G,2]; const k=[a,b].sort().join(); if(k==='ลม,ไฟ') return ['g','ธาตุสมพงศ์ ลมกระพือไฟให้ลุกโชน',G,2]; if(k==='ดิน,น้ำ') return ['g','ธาตุสมพงศ์ น้ำหล่อเลี้ยงดินให้งอกงาม',G,2]; if(k==='น้ำ,ไฟ') return ['b','ธาตุวิวาท น้ำดับไฟ เรื่องชะงัก',B,-2]; if(k==='ดิน,ลม') return ['b','ธาตุวิวาท ลมพัดหน้าดิน ไม่นิ่ง',B,-2]; return ['m',k==='ดิน,ไฟ'?'ธาตุกลาง ไฟเผาดินให้แข็ง ต้องใช้ความอดทน':'ธาตุกลาง ลมพัดผิวน้ำ อารมณ์แปรปรวนได้',Y,0]; };
const nrm=x=>((x%360)+360)%360, sg=x=>Math.floor(nrm(x)/30), cnt=(a,b)=>((b-a)%12+12)%12+1, DAY=864e5, YR=365.2425*DAY;
const tri=x=>{ const s=sg(x),t=Math.floor((nrm(x)-s*30)/10); return (s+4*t)%12; }, nav=x=>{ const s=sg(x),d=nrm(x)%30; return ([0,9,6,3][s%4]+Math.floor(d/(10/3)))%12; };
const sd=(k,x)=>{ try{ return std(k,x)||''; }catch(_){ return ''; } };
const dsc=s=>/มหาอุจจ์|อุจจ์/.test(s)?3:/เกษตร/.test(s)?2:/ราชาโชค|มหาจักร/.test(s)?1:/นิจ/.test(s)?-3:/ประ/.test(s)?-2:0;
const MO_=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'], WD=['อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์'];
const fdt=t=>{ const d=new Date(t); return `${td(d.getDate())} ${MO_[d.getMonth()]} ${td(d.getFullYear()+543)}`; };
const fdtm=t=>{ const d=new Date(t); return `วัน${WD[d.getDay()]} ${fdt(d)} ${td(String(d.getHours()).padStart(2,'0'))}:${td(String(d.getMinutes()).padStart(2,'0'))} น.`; };
const ymd=(a,b)=>{ a=new Date(a); b=new Date(b); let y=b.getFullYear()-a.getFullYear(), m=b.getMonth()-a.getMonth(), d=b.getDate()-a.getDate(); if(d<0){ m--; d+=new Date(b.getFullYear(),b.getMonth(),0).getDate(); } if(m<0){ y--; m+=12; } return [y,m,d]; };
const ymdT=([y,m,d])=>[y?td(y)+' ปี':'',m?td(m)+' เดือน':'',d||(!y&&!m)?td(d)+' วัน':''].filter(Boolean).join(' ');
