const nrm=x=>((x%360)+360)%360, sg=x=>Math.floor(nrm(x)/30), cnt=(a,b)=>((b-a)%12+12)%12+1, DAY=864e5, YR=365.2425*DAY;
const sd=(k,x)=>{ try{ return std(k,x)||''; }catch(_){ return ''; } }, dsc=s=>/อุจจ์/.test(s)?3:/เกษตร/.test(s)?2:/ราชาโชค|มหาจักร/.test(s)?1:/นิจ/.test(s)?-3:/ประ/.test(s)?-2:0;
