function ctx(){ const W=typeof WSTATE!=='undefined'?WSTATE:null; let T; try{ T=getTransit(); }catch(_){ } if(!T||isNaN(T)) T=new Date(); const o={T:+T}; if(W&&W.nat&&W.nat.pos){ o.N=W.nat2||W.nat.pos; o.L=sg(o.N.LA); o.bt=+W.bt; o.tanu=W.tanu; try{ const m=taksaNatal(new Date(o.bt)).m; o.TK={}; for(const r in m) o.TK[r]=P2K[m[r]]; }catch(_){ o.TK={}; } } o.TR=posAt(T); return X0=o; }
const jr=t=>{ try{ const m=taksaJrOf(new Date(X0.bt),new Date(t)), o={}; for(const r in m) o[r]=P2K[m[r]]; return o; }catch(_){ return {}; } };
function core(X){ const N=X.N, L=X.L, ps=(L+3)%12, lord=LRD[ps], lh=N[lord]!=null?cnt(L,sg(N[lord])):0, st=sd(lord,N[lord]), sc0=dsc(st);
const flo=KA.filter(k=>N[k]!=null&&sg(N[k])===ps), mula=X.TK['มูละ'], mst=mula?sd(mula,N[mula]):'', mh=mula?cnt(L,sg(N[mula])):0, tanu=X.tanu;
let sc=sc0+([6,8,12].includes(lh)?-2:[1,2,4,5,9,10,11].includes(lh)?1:0)+(dsc(mst)>0?1:dsc(mst)<0?-1:0)+([6,8,12].includes(mh)?-1:0)+flo.filter(k=>['JU','VE','MO','ME'].includes(k)).length*0.5-flo.filter(k=>['SA','RA','MA','KE'].includes(k)).length*0.5;
const nb=/นิจ/.test(st)&&typeof NB356==='function'&&NB356(lord,N).ok; if(nb) sc+=2;
const tl=tanu&&(tanu===lord||(N[tanu]!=null&&(sg(N[tanu])===ps||sg(N[tanu])===sg(N[lord]))));
return {ps,lord,lh,st,sc0,flo,mula,mst,mh,sc,nb,tl,inRad:[4,10].includes(ps)||[4,10].includes(N[lord]!=null?sg(N[lord]):-1)}; }
