function art(c1,c2){ return `<svg viewBox="0 0 300 150" class="bh8art" aria-hidden="true"><path d="M0 128h300" stroke="var(--line)" stroke-width="2"/><g><path d="M34 74l52-42 52 42" fill="none" stroke="${c1}" stroke-width="5" stroke-linejoin="round"/><rect x="46" y="72" width="80" height="56" rx="4" fill="${c1}" opacity=".85"/><rect x="76" y="96" width="20" height="32" rx="2" fill="var(--panel)"/><rect x="54" y="82" width="14" height="12" rx="2" fill="var(--panel)"/><rect x="104" y="82" width="14" height="12" rx="2" fill="var(--panel)"/><path d="M112 46v-14h10v22" fill="${c1}"/></g><g class="bh8car"><path d="M160 116v-14l12-18h68l18 18h14v14z" fill="${c2}" opacity=".9"/><path d="M176 100l8-12h22v12zM212 88h26l12 12h-38z" fill="var(--panel)" opacity=".85"/><circle cx="184" cy="118" r="10" fill="#222" stroke="var(--panel)" stroke-width="3"/><circle cx="246" cy="118" r="10" fill="#222" stroke="var(--panel)" stroke-width="3"/></g><g fill="#f3c94a"><path class="bh8sp" d="M150 26l3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/><path class="bh8sp b" d="M270 40l2 5 5 2-5 2-2 5-2-5-5-2 5-2z"/></g></svg>`; }
