function wheel(X){ try{ return `<div class="bh8w">${wheelF({id:'bh8w',natal:X.N,transit:X.TR,retro:{},retroT:{},mark:{},lagSign:X.L,center:['บ้าน รถ ที่ดิน',''],tanu:X.tanu,L:{}})}</div>`; }catch(e){ return ''; } }
function years(X,C,n){ const b=new Date(X.bt), out=[]; const now=Date.now(); const a0=ymd(b,now)[0]; for(let a=Math.max(0,a0-1);a<a0+n;a++){ const st=new Date(b); st.setFullYear(b.getFullYear()+a); const en=new Date(st); en.setFullYear(st.getFullYear()+1); const m=jr(+st+DAY); const sri=m['ศรี'], kal=m['กาลกิณี']; const why=[]; if(sri===C.lord) why.push(['g',`ดาวพันธุ (${TN[C.lord]}) เป็นศรีจร`]); C.flo.forEach(k=>{ if(sri===k) why.push(['g',`ดาวลอยในภพพันธุ (${TN[k]}) เป็นศรีจร`]); }); if(C.mula&&sri===C.mula) why.push(['g',`ดาวมูละเดิม (${TN[C.mula]}) เป็นศรีจร`]); if(m['มูละ']===C.lord) why.push(['m',`ดาวพันธุเป็นมูละจร (หลักฐานบ้านช่องเด่น)`]); if(kal===C.lord) why.push(['b',`ดาวพันธุเป็นกาลกิณีจร ระวังเรื่องบ้านรถ`]); out.push({a:a+1,st:+st,en:+en,sri,kal,why,g:why.filter(w=>w[0]==='g').length,b:why.some(w=>w[0]==='b')}); } return out; }
function jwin(X,C,from,to){ const R=[]; const tg=[[C.ps,'พฤหัสบดีจรเข้าภพพันธุ'],[(X.L+1)%12,'พฤหัสบดีจรเข้าภพกดุมภะ (บ้านที่ซื้อเอง)']]; if(X.N[C.lord]!=null) tg.push([sg(X.N[C.lord]),'พฤหัสบดีจรทับดาวพันธุเดิม']);
for(const [s,why] of tg){ let t=from, inn=sg(posAt(t).JU)===s, a=inn?t:null; for(;t<to;t+=3*DAY){ const z=sg(posH(horaOf(new Date(t)),'JU'))===s; if(z&&!inn){ a=t; inn=true; } if(!z&&inn){ R.push({a,b:t,why}); inn=false; } } if(inn) R.push({a,b:null,why}); }
const lk=C.lord; if(lk!=='JU'){ let t=from, prev=null; const st=['SA','RA'].includes(lk)?5:2; for(;t<to;t+=st*DAY){ const x=posH(horaOf(new Date(t)),lk); const ok=dsc(sd(lk,x))>0; if(ok&&prev===false||ok&&prev===null) R.push({a:t,b:null,why:`${TN[lk]} (ดาวพันธุ) จรได้มาตรฐาน${sd(lk,x)}`,lk:1}); prev=ok; } }
return R.sort((p,q)=>p.a-q.a); }
function tOv(X){ const C=core(X), c=vcol(C.sc), lc=COL[C.lord][1], ys=years(X,C,30), nx=ys.find(y=>y.g&&y.en>Date.now());
return `${art(lc,COL[(C.flo[0]&&COL[C.flo[0]])?C.flo[0]:C.lord][1])}<div class="bh8sum"><div style="--c:${c}">${ic('home',c,22)}<b>${C.sc>=2?'พื้นดวงบ้านรถเด่น':C.sc<=-1?'ต้องใช้ความพยายาม':'ปานกลาง'}</b><small>คะแนนพื้นดวง ${C.sc>0?'+':''}${td(Math.round(C.sc*10)/10)}</small></div><div style="--c:${PC[C.lord]}">${pl(C.lord)}<b>ดาวพันธุ: ${TN[C.lord]}</b><small>ภพพันธุราศี${SN[C.ps]} · ไปอยู่${HN[C.lh-1]}${C.st?' · '+C.st:''}</small></div><div style="--c:${G}">${ic('star',G,22)}<b>${nx?'อายุ '+td(nx.a)+' ปี':'—'}</b><small>${nx?`ปีศรีจรถัดไป เริ่ม ${fdt(nx.st)} (${left(nx.st)})`:'ไม่พบใน ๓๐ ปี'}</small></div></div>${wheel(X)}
${card(GD,'palette','สรุปสั้น',`<ul class="bh8l">${li(C.sc>=2?'g':C.sc<=-1?'b':'m',`ดาวพันธุ ${TN[C.lord]} ${C.st||'ไม่มีมาตรฐานพิเศษ'} ไปอยู่ภพ${HN[C.lh-1]}: ${LH[C.lh][1]}`)}${li('m',`รถที่เข้ากับดวง: ${CAR[C.lord]} · สีมงคล ${sw(C.lord)}`)}${li('m',`บ้านที่เข้ากับดวง: ${HOME[C.lord]}`)}${nx?li('g',`ปีที่มีโอกาสได้บ้าน รถ ที่ดิน: อายุ ${td(nx.a)} ปี (${fdt(nx.st)} ถึง ${fdt(nx.en)})`):''}</ul>`)}`; }
function tNt(X){ const C=core(X), N=X.N, L=X.L, lr=LH[C.lh];
const h2=LRD[(L+1)%12], h9=LRD[(L+8)%12], hh=k=>N[k]!=null?cnt(L,sg(N[k])):0;
return `${card(vcol(C.sc),'land',`ดาวพันธุ ${TN[C.lord]} (เจ้าเรือนภพพันธุราศี${SN[C.ps]})`,`<p>มาตรฐาน: ${C.st?tag(C.st,C.sc0>0?G:C.sc0<0?B:Y):tag('ไม่มีมาตรฐานพิเศษ',GR)}${C.nb?' '+tag('นิจภังค์ ไม่ส่งผลร้าย',G):''} · ไปอยู่<b>ภพ${HN[C.lh-1]}</b>${[6,8,12].includes(C.lh)?' '+tag('ทุสถานะ',B):''}</p><ul class="bh8l">${li('g','ด้านดี: '+lr[1])}${li('b','ด้านเสีย: '+lr[2])}</ul><p class="note">ตำราเตือนว่าการจะดีหรือร้ายต้องดูกำลังของดาวประกอบเสมอ ดาวพันธุที่ไม่ตกภพอริ มรณะ วินาศ จะทำให้หลักทรัพย์มั่นคง</p>`)}
${card(A,'home','ดาวลอยในภพพันธุ',C.flo.length?`<ul class="bh8l">${C.flo.map(k=>li(['JU','VE','MO','ME'].includes(k)?'g':['SA','RA','MA','KE'].includes(k)?'b':'m',`${pl(k)} ${TN[k]}: รถแบบ${CAR[k]} · บ้านแบบ${HOME[k]}`)).join('')}</ul><p class="note">ตำราว่าคนที่มีดาวลอยในภพพันธุ ให้เน้นดูดาวลอยด้วย ถ้าปีใดดาวลอยเป็นศรีจรก็มีโอกาสเช่นกัน</p>`:'<p class="note">ไม่มีดาวลอยในภพพันธุ</p>')}
${card(Y,'star',`ดาวมูละเดิม (ตามวันเกิด): ${C.mula?TN[C.mula]:'—'}`,C.mula?`<p>${pl(C.mula)} ${TN[C.mula]} อยู่ภพ${HN[C.mh-1]}${C.mst?' เป็น'+C.mst:''} ${dsc(C.mst)>0&&![6,8,12].includes(C.mh)?tag('มูละดี หลักฐานบ้านช่องมั่นคง',G):[6,8,12].includes(C.mh)||dsc(C.mst)<0?tag('มูละอ่อน ต้องสร้างหลักฐานด้วยความพยายาม',B):tag('มูละปานกลาง',Y)}</p><p class="note">มูละคือที่อยู่อาศัยและหลักฐาน ตำราว่าคนที่มีบ้าน รถ ที่ดินมักมีดาวพันธุดีและดาวมูละดี</p>`:'')}
${C.tl?card('#e05f8a','heart','ดาวตนุเศษเชื่อมกับภพพันธุ',`<p>ดาวตนุเศษ (${TN[X.tanu]}) ${X.tanu===C.lord?'เป็นดาวพันธุเอง':'อยู่ภพพันธุหรือร่วมราศีกับดาวพันธุ'} ตำราว่าเป็นคนรักบ้าน รักครอบครัว รักรถ หวงของ และมักผูกพันกับแม่มาก</p>`):''}
${card(GR,'grid','บ้าน ๓ แบบตามภพ',`<div class="kh8tw"><table class="kh8tb"><tr><th>ภพ</th><th>หมายถึง</th><th>เจ้าเรือน</th><th>ไปอยู่</th><th>มาตรฐาน</th></tr>${[[4,C.lord,'บ้านเกิด บ้านแรก'],[2,h2,'บ้านที่ซื้อเองหรือสร้างเอง'],[9,h9,'บ้านเช่า บ้านจำนอง ผ่อนธนาคาร']].map(([h,k,t])=>{ const s=sd(k,N[k]); return `<tr><td>${HN[h-1]}</td><td>${t}</td><td>${pl(k)} ${TN[k]}</td><td>${HN[hh(k)-1]}</td><td style="color:${dsc(s)>0?G:dsc(s)<0?B:'inherit'}">${s||'—'}</td></tr>`; }).join('')}</table></div>`)}`; }
function tTm(X){ const C=core(X); const ys=years(X,C,25); if(!SCAN){ const now=Date.now(); SCAN=jwin(X,C,now,now+12*YR); }
const good=ys.filter(y=>y.g&&y.en>Date.now()), J=SCAN;
const yr=y=>`<tr class="${y.st<=Date.now()&&y.en>Date.now()?'on':''}"><td>${td(y.a)}</td><td>${fdt(y.st)}</td><td>${pl(y.sri)} ${TN[y.sri]}</td><td>${pl(y.kal)} ${TN[y.kal]}</td><td>${y.why.map(w=>`<span style="color:${w[0]==='g'?G:w[0]==='b'?B:Y}">${w[1]}</span>`).join('<br>')||'—'}</td><td>${y.st<=Date.now()&&y.en>Date.now()?'ปีปัจจุบัน':left(y.st)}</td></tr>`;
return `${card(G,'star','ปีที่ดาวพันธุเป็นศรีจร (โอกาสได้บ้าน รถ ที่ดิน)',good.length?`<ul class="bh8l">${good.slice(0,5).map(y=>li('g',`<b>อายุ ${td(y.a)} ปี</b> ${fdt(y.st)} ถึง ${fdt(y.en)} · ${y.st<=Date.now()?'กำลังอยู่ในปีนี้':left(y.st)}: ${y.why.filter(w=>w[0]==='g').map(w=>w[1]).join(' · ')} มีโอกาสได้รถ บ้าน ที่ดิน และโชคจากเลขรถ เลขบ้าน`)).join('')}</ul>`:'<p class="note">ใน ๒๕ ปีข้างหน้าไม่พบปีที่ดาวพันธุเป็นศรีจร</p>')}
${card(A,'cal','ช่วงเดือนที่เหมาะภายในปี (ดาวจร)',`<ul class="bh8l">${J.slice(0,12).map(w=>li('g',`<b>${fdtm(w.a)}</b>${w.b?' ถึง '+fdt(w.b):''} · ${left(w.a)} · อายุ ${ageAt(w.a)}: ${w.why}`)).join('')}</ul><p class="note">ช่วงที่ดีที่สุดคือปีศรีจรที่ซ้อนกับช่วงพฤหัสบดีจรเข้าภพพันธุหรือภพกดุมภะ</p>`)}
${card(GR,'grid','ทักษาจรรายปี',`<div class="kh8tw"><table class="kh8tb"><tr><th>อายุย่าง</th><th>เริ่มปี</th><th>ศรีจร</th><th>กาลกิณีจร</th><th>เกณฑ์บ้านรถ</th><th>นับถอยหลัง</th></tr>${ys.slice(0,14).map(yr).join('')}</table></div><p class="note">ใช้ทักษาจรแบบเดียวกับหน้าหลักของแอป ปีทักษาเปลี่ยนในวันเกิดของแต่ละปี</p>`)}`; }
function tTy(X){ const C=core(X), TK=X.TK, kal=TK['กาลกิณี'], sri=TK['ศรี'], m=jr(Date.now());
const cand=[C.lord,...C.flo.filter(k=>k!==C.lord&&COL[k])].filter((k,i,a)=>a.indexOf(k)===i);
const nums=[...new Set([C.lord,sri,m['ศรี'],C.mula].filter(Boolean).map(k=>PN[k]))];
return `${art(COL[C.lord][1],COL[sri&&sri!==kal?sri:C.lord][1])}
${card(GD,'car','รถที่เข้ากับดวง',`<ul class="bh8l">${cand.map(k=>li('g',`${pl(k)} ${TN[k]}: ${CAR[k]} · สี ${sw(k)}`)).join('')}</ul>${[6].includes(C.lh)?'<p class="note">ดาวพันธุอยู่ภพอริ ตำราว่ารถมักต้องซ่อมบำรุงบ่อย ควรเลือกรถที่ศูนย์บริการสะดวก</p>':C.lh===11?'<p class="note">ดาวพันธุอยู่ภพลาภะ ตำราว่ารถนำโชคและผลประโยชน์มาให้</p>':''}`)}
${card(A,'home','บ้านและที่ดินที่เข้ากับดวง',`<ul class="bh8l">${cand.map(k=>li('g',`${pl(k)} ${TN[k]}: ${HOME[k]}`)).join('')}</ul>`)}
${card('#e05f8a','palette','สีมงคลและสีที่ควรเลี่ยง',`<div class="bh8cl"><div>${ic('ok',G,16)} สีจากดาวพันธุ ${sw(C.lord)}</div>${sri?`<div>${ic('ok',G,16)} สีศรีตามวันเกิด (${TN[sri]}) ${sw(sri)}</div>`:''}${m['ศรี']?`<div>${ic('star',G,16)} สีศรีจรปีนี้ (${TN[m['ศรี']]}) ${sw(m['ศรี'])}</div>`:''}${kal?`<div>${ic('no',B,16)} เลี่ยงสีกาลกิณีวันเกิด (${TN[kal]}) ${sw(kal)}</div>`:''}</div>${kal===C.lord?'<p class="note">ดาวพันธุตรงกับดาวกาลกิณีวันเกิด ระบบจึงแนะนำสีศรีเป็นหลัก</p>':''}`)}
${card(Y,'hash','เลขมงคลสำหรับทะเบียนรถ เลขที่บ้าน',`<p>เลขที่ควรมีในชุดเลข: ${nums.map(n=>`<b class="bh8n">${n}</b>`).join(' ')} (เลขประจำดาวพันธุ ดาวศรี ดาวศรีจร และดาวมูละ)</p>${kal?`<p class="note">ควรเลี่ยงเลข ${PN[kal]} (ดาวกาลกิณีวันเกิด)</p>`:''}`)}`; }
function tMn(X){ const C=X.N?core(X):null, L=X.L;
const tl=X.N&&X.N[LRD[L]]!=null?cnt(L,sg(X.N[LRD[L]])):0;
return `${card(GD,'grid','ความหมายของภพพันธุ',`<div class="bh8m">${MEAN.map(m=>`<div><b>${m[0]}</b><span>${m[1]}</span></div>`).join('')}</div>`)}
${card(A,'home','พันธุไปอยู่ภพใด อ่านสัมพันธ์ตามไป',`<div class="kh8tw"><table class="kh8tb"><tr><th>ดาวพันธุอยู่ภพ</th><th>ด้านดี</th><th>ด้านเสีย</th></tr>${Object.entries(LH).map(([h,v])=>`<tr class="${C&&C.lh==h?'on':''}"><td>${HN[h-1]}</td><td>${v[1]}</td><td>${v[2]}</td></tr>`).join('')}</table></div><p class="note">ตัวอย่างการอ่านคู่ภพ: ${COMBO.map(c=>`พันธุ–${c[1]} = ${c[2]}`).join(' · ')}</p>`)}
${card(Y,'heart','ภพผสมภพ: ดาวตนุ (เจ้าเรือนลัคนา) ไปอยู่ภพใด',`<div class="kh8tw"><table class="kh8tb">${Object.entries(TANU).map(([h,v])=>`<tr class="${tl==h?'on':''}"><td>ตนุอยู่${HN[h-1]}</td><td>${v}</td></tr>`).join('')}</table></div>`)}
${card(GR,'grid','ดาวพันธุตามลัคนา',`<div class="kh8tw"><table class="kh8tb"><tr><th>ลัคนา</th><th>ภพพันธุ</th><th>ดาวพันธุ</th></tr>${SN.map((n,l)=>`<tr class="${l===L?'on':''}"><td>${n}</td><td>${SN[(l+3)%12]}</td><td>${pl(LRD[(l+3)%12])} ${TN[LRD[(l+3)%12]]}</td></tr>`).join('')}</table></div>`)}`; }
function tHow(){ return `<div class="kh8tw"><table class="kh8tb"><tr><td><b>ภพพันธุ</b></td><td>ภพที่ ๔ จากลัคนา หมายถึงบ้านเกิด แม่ ญาติ รถ ที่ดิน อสังหา รากฐานของครอบครัว</td></tr><tr><td><b>ดาวพันธุ</b></td><td>เจ้าเรือนของราศีภพพันธุ ต้องไม่อยู่อริ มรณะ วินาศ ถ้าได้อุจจ์ เกษตร ราชาโชค มหาจักร ยิ่งดี</td></tr><tr><td><b>ปีที่จะได้บ้านรถ</b></td><td>ปีที่ดาวพันธุ ดาวลอยในภพพันธุ หรือดาวมูละเดิมเป็นศรีจรในทักษาจรรายปี</td></tr><tr><td><b>ช่วงเดือน</b></td><td>พฤหัสบดีจรเข้าภพพันธุ ภพกดุมภะ หรือทับดาวพันธุเดิม และช่วงที่ดาวพันธุจรได้มาตรฐานดี</td></tr><tr><td><b>บ้าน ๓ ภพ</b></td><td>พันธุ = บ้านเกิด · กดุมภะ = บ้านที่ซื้อเอง · ศุภะ = บ้านเช่าหรือบ้านผ่อน</td></tr><tr><td><b>แบบรถ บ้าน สี เลข</b></td><td>อ่านจากธรรมชาติของดาวพันธุและดาวลอยในภพพันธุ สีประจำดาวแบบไทย เลขประจำดาว (การให้แบบรถ บ้าน และสี เป็นการตีความต่อยอดของระบบ)</td></tr><tr><td><b>คะแนนพื้นดวง</b></td><td>มาตรฐานดาวพันธุ (อุจจ์ +๓ เกษตร +๒ ราชาโชค มหาจักร +๑ ประ −๒ นิจ −๓) + ภพที่ไป (ดี +๑ ทุสถานะ −๒) + มูละดี +๑ อ่อน −๑ + ดาวลอยศุภ +½ บาป −½ + นิจภังค์ +๒</td></tr></table></div><p class="note">ที่มา: ความหมายภพพันธุ และพันธุสถิตภพต่าง ๆ จากบทความที่ อ.ดุ๊ก ส่งมา · ดาวพันธุเป็นศรีจร และดาวมูละตามวันเกิด จากบทความอังกอร์ศรีดุสิต · บ้าน ๓ ภพและดาวตนุเศษกับภพพันธุ จากครูโอ มงคลราชาโชค · ดาวในภพพันธุกับลักษณะรถ จากบทความที่แนบ ระบบเรียบเรียงใหม่ทั้งหมด ตัดช่องทางติดต่อออก ตำราเตือนว่าดวงบอกแค่โอกาส ต้องอาศัยความพร้อมและความพยายามของเจ้าชะตาด้วย</p>`; }
function render(){ const out=document.getElementById('bh378Out'); if(!out) return; let X={}; try{ X=ctx(); }catch(e){ console.error(e); } let b='';
try{ if(!X.N&&!['how'].includes(TAB)) b='<p class="note">ผูกดวงก่อน แล้วกลับมาที่หน้านี้</p>'; else b=({ov:tOv,nt:tNt,tm:tTm,ty:tTy,mn:tMn,how:tHow})[TAB](X); }catch(e){ console.error(e); b='<p class="note">คำนวณไม่สำเร็จ</p>'; }
out.innerHTML=`<h3 class="kh8H">${ic('home',GD,24)} บ้าน รถ ที่ดิน (ภพพันธุ)</h3><p class="note">ตรวจว่าจะได้บ้านหรือรถไหม ได้เมื่อไหร่ แบบไหน สีอะไร จากดาวพันธุ ดาวลอย ดาวมูละ และทักษาจร</p><div class="kh8tabs">${TABS.map(([k,i,t])=>`<button type="button" data-bhb="${k}" class="${TAB===k?'on':''}">${ic(i,TAB===k?GD:null,20)}<span>${t}</span></button>`).join('')}</div>${b}`; }
